(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,63059,69251,e=>{"use strict";let t=(0,e.i(75254).default)("chevron-right",[["path",{d:"m9 18 6-6-6-6",key:"mthhwq"}]]);e.s(["ChevronRight",()=>t],63059);let o={"english-basics":{title:"Alphabet & Phonics",color:"#fbbf24",sections:[{id:"en-basics-sec",title:"Fundamentals",unlocked:!0,lessons:[{id:"english-basics",title:"Alphabet & Phonics",icon:"🔤",xp:10,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"The Letter A",content:'A is for Apple. It makes an "ah" sound.'},{type:"multiple_choice",question:"Which word starts with A?",options:["Banana","Apple","Cat"],correct:1}]}]}]},"robotics-kids":{title:"Visual Logic: Block Robotics",color:"#60a5fa",sections:[{id:"robotics-sec",title:"Intro to Robotics",unlocked:!0,lessons:[{id:"robotics-kids",title:"Visual Logic: Block Robotics",icon:"🤖",xp:15,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Commanding the Bot",content:'Drag the "Move Forward" block.'},{type:"multiple_choice",question:"To turn right?",options:["Turn Left","Turn Right"],correct:1}]}]}]},english:{title:"English Adventure",color:"#fbbf24",sections:[{id:"en-a1",title:"A1 — Beginner",tier:"A1",unlocked:!0,lessons:[{id:"en-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:100,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"I ___ a student.",options:["is","am","are"],correct:1},{type:"multiple_choice",question:"She ___ two cats.",options:["have","has","having"],correct:1,explanation:"With he/she/it the verb takes -s: has, not have."},{type:"multiple_choice",question:"They ___ from Spain.",options:["is","am","are"],correct:2,explanation:"Plural subjects (they, we, you) take are."},{type:"multiple_choice",question:"Which sentence is a question?",options:["You are tired.","Are you tired?","You tired are."],correct:1,explanation:"A yes/no question in English moves the verb to be in front of the subject."}]}]},{id:"en-a2",title:"A2 — elementary",tier:"A2",unlocked:!0,lessons:[{id:"en-a2-test",title:"A2 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"I have ___ finished my homework.",options:["already","yet","still"],correct:0,explanation:"Already is used in affirmative sentences with the present perfect to show something happened sooner than expected."},{type:"multiple_choice",question:"If it rains, I ___ stay home.",options:["will","would","am"],correct:0,explanation:"First conditional: if + present, will + base verb, for a real future possibility."},{type:"multiple_choice",question:"This book is ___ than that one.",options:["interesting","more interesting","most interesting"],correct:1,explanation:"Comparing two things uses the comparative form: more interesting."},{type:"multiple_choice",question:"She said she ___ tired.",options:["is","was","be"],correct:1,explanation:"Reported speech shifts present tense back one step into the past: is becomes was."}]}]},{id:"en-b1",title:"B1 — Intermediate",tier:"B1",unlocked:!0,lessons:[{id:"en-b1-test",title:"B1 Proficiency Test",icon:"🔯",xp:200,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"By the time we arrived, the film ___ already started.",options:["has","had","have"],correct:1,explanation:"Past perfect (had + past participle) marks an action completed before another past action."},{type:"multiple_choice",question:"The report ___ by the team yesterday.",options:["was written","wrote","is writing"],correct:0,explanation:"The passive voice (was + past participle) is used when the focus is on the report, not who wrote it."},{type:"multiple_choice",question:"I wish I ___ more time to prepare.",options:["have","had","will have"],correct:1,explanation:"Wish + past tense expresses regret about a present situation."},{type:"multiple_choice",question:"Choose the correctly punctuated sentence.",options:["Although it was raining, we went out.","Although it was raining we went out","Although, it was raining, we went out."],correct:0,explanation:"A comma follows an introductory subordinate clause; none belongs after although."}]}]}]},spanish:{title:"Spanish Quest",color:"#ef4444",sections:[{id:"sp-a1",title:"A1 — The Beginning",tier:"A1",unlocked:!0,lessons:[{id:"sp-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:100,unlocked:!0,type:"test",work:"control",exercises:[{type:"translate",question:"Hola",correct:"Hello"},{type:"translate",question:"Gracias",correct:"Thank you",acceptable:["Thanks"]},{type:"multiple_choice",question:"Yo ___ estudiante.",options:["soy","eres","es"],correct:0,explanation:"Soy is the first-person singular of ser (to be): yo soy."},{type:"multiple_choice",question:'"La casa" means',options:["the house","a house","her house"],correct:0,explanation:"La is the feminine definite article the; casa is feminine."}]}]},{id:"sp-a2",title:"A2 — Fundamental",tier:"A2",unlocked:!0,lessons:[{id:"sp-a2-test",title:"A2 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"Ayer yo ___ al cine.",options:["voy","fui","iré"],correct:1,explanation:"Fui is the preterite of ir (to go), used for a completed action in the past: ayer fui."},{type:"multiple_choice",question:'"Estoy cansado" means',options:["I am tired","I am a teacher","I am here"],correct:0,explanation:"Estar is used for temporary states like tiredness; cansado means tired."},{type:"translate",question:"el libro",correct:"the book"},{type:"multiple_choice",question:'Which is correct for "we eat"?',options:["comemos","comen","como"],correct:0,explanation:"Comemos is the first-person plural (nosotros) form of comer."}]}]}]},german:{title:"German Pursuit",color:"#fde047",sections:[{id:"de-a1",title:"A1 — Beginner",tier:"A1",unlocked:!0,lessons:[{id:"de-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:100,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"Hallo?",options:["Hello","Bye"],correct:0}]}]}]},catalan:{title:"Català Discovery",color:"#f97316",sections:[{id:"ca-base",title:"Mediterranean Basics",unlocked:!0,lessons:[{id:"ca-l1",title:"First Words",icon:"☀️",xp:12,unlocked:!0,work:"classwork",exercises:[{type:"multiple_choice",question:"Bon dia?",options:["Good morning","Good night"],correct:0}]}]}]},ukrainian:{title:"Ukrainian Heart",color:"#ffd700",sections:[{id:"uk-a1",title:"A1 — Beginnings",tier:"A1",unlocked:!0,lessons:[{id:"uk-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"translate",question:"Дякую",correct:"Thank you",acceptable:["Thanks"]},{type:"multiple_choice",question:'"Привіт" is used to say',options:["Hello","Goodbye","Please"],correct:0,explanation:"Привіт is an informal greeting, equivalent to hello or hi."},{type:"multiple_choice",question:"Я ___ студент.",options:["є","(nothing, dropped)","був"],correct:1,explanation:'The present-tense form of "to be" is normally omitted in Ukrainian: Я студент, not Я є студент.'},{type:"translate",question:"книга",correct:"book"}]}]}]},russian:{title:"Russian Legacy",color:"#3b82f6",sections:[{id:"ru-a1",title:"A1 — Basics",tier:"A1",unlocked:!0,lessons:[{id:"ru-a1-test",title:"A1 Proficiency Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"translate",question:"Спасибо",correct:"Thank you",acceptable:["Thanks"]},{type:"multiple_choice",question:'"Привет" is used to say',options:["Hello","Goodbye","Sorry"],correct:0,explanation:"Привет is an informal greeting, equivalent to hello or hi."},{type:"multiple_choice",question:"Choose the correct form: Я ___ книгу.",options:["читаю","читаешь","читает"],correct:0,explanation:"Читаю is the first-person singular (I read) form of читать."},{type:"translate",question:"дом",correct:"house"}]}]}]},physics:{title:"Applied Physics",color:"#06b6d4",sections:[{id:"ph-a1",title:"Phase 1: Motion",tier:"A1",unlocked:!0,lessons:[{id:"ph-l1",title:"Newtonian Laws",icon:"🍎",xp:20,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"First Law of Motion",content:"An object at rest stays at rest unless acted upon by a force."},{type:"multiple_choice",question:"Who defined the Laws of Motion?",options:["Einstein","Newton","Curie"],correct:1}]},{id:"ph-a1-test",title:"Physics A1 Test",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"An object at rest stays at rest unless acted on by a",options:["force","shadow","clock"],correct:0,explanation:"This is Newton’s First Law: no net force, no change in motion."},{type:"multiple_choice",question:"Newton’s Second Law relates force, mass and",options:["temperature","acceleration","color"],correct:1,explanation:"F = m * a: force equals mass times acceleration."},{type:"multiple_choice",question:"Newton’s Third Law says every action has an equal and opposite",options:["reaction","shadow","delay"],correct:0,explanation:"Forces always come in equal, opposite pairs between two bodies."},{type:"multiple_choice",question:"If two objects are each in thermal equilibrium with a third, they are",options:["in equilibrium with each other","always at the same pressure","unrelated"],correct:0,explanation:"This is the 0th law of thermodynamics: equilibrium with a common third body implies equilibrium with each other."}]}]},{id:"ph-a2",title:"Phase 2: Energy",tier:"A2",unlocked:!0,lessons:[{id:"ph-l2",title:"Conservation of Energy",icon:"⚡",xp:40,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Energy Conservation",content:"Energy cannot be created or destroyed, only transformed."},{type:"multiple_choice",question:"Kinetic energy is energy of?",options:["Rest","Motion","Height"],correct:1}]}]}]},"nature-basics":{title:"How Things Behave",color:"#65a30d",sections:[{id:"nat-a1",title:"Water and ice",tier:"A1",unlocked:!0,lessons:[{id:"nat-l1",title:"Why ice floats",icon:"🧊",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Ice floats because it is less crowded",content:"When water freezes, its molecules lock into a loose, spread-out lattice instead of a tightly packed liquid. Spreading out means the same amount of matter now takes up more room, so ice is lighter than the same volume of liquid water. Anything lighter than the liquid around it floats."},{type:"multiple_choice",question:"Why does an ice cube float in a glass of water?",options:["Ice is warmer than water","Ice takes up more space than the same water did as liquid","Ice is a different substance from water"],correct:1,explanation:"Freezing spreads the water molecules into a wider lattice, so the same mass of ice has a larger volume and floats."},{type:"multiple_choice",question:"What would happen to icebergs if ice were denser than liquid water instead of lighter?",options:["Nothing would change","They would sink to the bottom","They would melt faster"],correct:1,explanation:"Something denser than the liquid around it sinks; icebergs float only because ice is less dense than water."}]},{id:"nat-l2",title:"Why shadows change",icon:"🌤️",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A shadow is a light gap",content:"Light travels in straight lines, so a shadow is simply the space an object blocks light from reaching. As the sun moves across the sky through the day, the angle the light arrives at changes, so the blocked shape stretches or shrinks and swings around."},{type:"multiple_choice",question:"Why are shadows long in the early morning and short at noon?",options:["The sun is closer at noon","The sun is higher in the sky at noon, so light comes down more steeply","Shadows only exist in the morning"],correct:1,explanation:"Low, slanting light at sunrise stretches a shadow far along the ground; overhead light at noon casts a short one."},{type:"multiple_choice",question:"What is a shadow, physically?",options:["A copy of the object made of dark material","An area light does not reach because something blocks it","A reflection of the object"],correct:1,explanation:"Light moves in straight lines; an opaque object blocks that path and the unlit region behind it is the shadow."}]}]},{id:"nat-a2",title:"Sound and air",tier:"A2",unlocked:!0,lessons:[{id:"nat-l3",title:"Why sound travels",icon:"🔊",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Sound is a wobble passed along",content:"A sound starts as something vibrating, like a drum skin or your throat. That vibration pushes on the air next to it, which pushes on the air next to that, and so on outward -- a wobble handed from one bit of air to the next until it reaches your ear."},{type:"multiple_choice",question:"Why can you not hear sound in outer space?",options:["Space is too dark","There is no air for the vibration to pass through","The sun blocks sound waves"],correct:1,explanation:"Sound needs a medium -- air, water, a solid -- to carry the vibration from one place to the next; space is a near-vacuum."},{type:"multiple_choice",question:"What actually moves outward when a sound is made?",options:["A wobble passed from one bit of air to the next","Tiny pieces of air flying to your ear","Nothing physically moves"],correct:0,explanation:"Each bit of air pushes its neighbour and springs back; it is the disturbance that travels, not any single parcel of air."}]},{id:"nat-l4",title:"Why things rust",icon:"🔧",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Rust is iron slowly reacting with air",content:"Iron left out in damp air slowly combines with oxygen and water to form a new, crumbly reddish substance -- rust. It is a real chemical change, not dirt sitting on top: the iron itself is being used up and turned into something else."},{type:"multiple_choice",question:"Why does an iron nail rust faster outdoors in the rain than indoors in a dry cupboard?",options:["Rain paints it red","Rust needs both water and oxygen from the air, and rain supplies the water","Indoor air has no oxygen"],correct:1,explanation:"Rusting is a reaction between iron, water and oxygen; without the water the reaction is far slower."},{type:"multiple_choice",question:"Is rusting a physical change (same substance, different shape) or a chemical change (a new substance forms)?",options:["Physical change","Chemical change","Neither"],correct:1,explanation:"The iron atoms combine with oxygen and water to make a genuinely different substance, rust -- that is a chemical change."}]}]},{id:"nat-b1",title:"Putting it together",tier:"B1",unlocked:!0,lessons:[{id:"nat-l5",title:"Why the sky is blue",icon:"🌈",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Blue light scatters more than red",content:"Sunlight looks white but is really every colour mixed together. As it passes through the air, tiny gas molecules scatter blue light around the sky far more than they scatter red light, so wherever you look away from the sun, you catch mostly scattered blue."},{type:"multiple_choice",question:"Why does the sky look blue rather than white or red on a clear day?",options:["The sky is naturally blue-coloured","Air molecules scatter blue light much more than red light","Blue light is the only colour the sun makes"],correct:1,explanation:"Sunlight contains all colours; air scatters the shorter-wavelength blue light strongly in every direction, filling the sky with it."},{type:"multiple_choice",question:"At sunset the sky often turns orange or red. Why?",options:["The sun changes colour at that time","Sunlight travels through much more air, scattering away most of the blue before it reaches your eyes","The moon is blocking the blue light"],correct:1,explanation:"At a low angle sunlight crosses far more atmosphere; most blue is scattered out along the way, leaving red and orange."}]},{id:"nat-l6",title:"How Things Behave: review",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"Ice floats on water because",options:["ice is warmer","ice takes up more space than the same mass of liquid water","ice is a different chemical"],correct:1,explanation:"Freezing spreads water molecules into a wider lattice, making ice less dense than liquid water."},{type:"multiple_choice",question:"Shadows change shape through the day because",options:["the object changes shape","the angle of sunlight changes as the sun moves across the sky","clouds paint them"],correct:1,explanation:"A shadow is where light is blocked; a lower sun angle stretches it, a higher one shortens it."},{type:"multiple_choice",question:"Sound cannot travel through empty space because",options:["space is too cold","sound needs a medium like air to carry its vibration","space is too bright"],correct:1,explanation:"Sound is a vibration passed from one bit of matter to the next; a vacuum has nothing to pass it along."},{type:"multiple_choice",question:"Rusting is a chemical change because",options:["iron just gets a red coating on top","the iron combines with oxygen and water to form a new substance","nothing about the iron actually changes"],correct:1,explanation:"A chemical change means a new substance forms; rust is genuinely different from the iron it came from."},{type:"multiple_choice",question:"The sky looks blue because",options:["air scatters blue light more than red light","the sky is naturally blue-coloured","the sun only emits blue light"],correct:0,explanation:"Sunlight carries every colour; air scatters shorter-wavelength blue light most strongly across the sky."}]}]}]},"chemistry-basics":{title:"Matter and Reaction",color:"#10b981",sections:[{id:"chem-a1",title:"Elements and symbols",tier:"A1",unlocked:!0,lessons:[{id:"chem-l1",title:"Elements have symbols",icon:"⚛️",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Every element has a one- or two-letter symbol",content:"An element is a substance made of only one kind of atom. Chemists write each one with a short symbol: H for hydrogen, O for oxygen, C for carbon, N for nitrogen, Na for sodium, Cl for chlorine. The first letter is always capital; a second letter, if there is one, is lowercase."},{type:"multiple_choice",question:"What does the symbol O stand for?",options:["Oxygen","Osmium","Ozone"],correct:0,explanation:"O is the symbol for oxygen."},{type:"multiple_choice",question:"What does the symbol Na stand for?",options:["Nitrogen","Sodium","Neon"],correct:1,explanation:"Na is the symbol for sodium (from its Latin name, natrium)."},{type:"multiple_choice",question:"What is the symbol for carbon?",options:["Ca","Co","C"],correct:2,explanation:"Carbon’s symbol is simply C."}]},{id:"chem-l2",title:"Reading a formula",icon:"💧",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A formula counts atoms",content:"A chemical formula lists the elements in a substance and how many atoms of each. H2O means two hydrogen atoms and one oxygen atom joined together: water. CO2 means one carbon atom and two oxygen atoms: carbon dioxide. NaCl means one sodium atom and one chlorine atom: table salt."},{type:"multiple_choice",question:"How many hydrogen atoms are in one molecule of H2O?",options:["1","2","3"],correct:1,explanation:"The subscript 2 after H means two hydrogen atoms; water is H2O."},{type:"multiple_choice",question:"CO2 is the formula for",options:["carbon monoxide","carbon dioxide","calcium oxide"],correct:1,explanation:"One carbon atom plus two oxygen atoms is carbon dioxide, CO2."},{type:"translate",question:"Write the formula for table salt (sodium chloride): one sodium atom, one chlorine atom.",correct:"NaCl",acceptable:["NaCl","nacl"],explanation:"One sodium (Na) and one chlorine (Cl) atom gives NaCl."}]}]},{id:"chem-a2",title:"Balancing an equation",tier:"A2",unlocked:!0,lessons:[{id:"chem-l3",title:"Atoms are never lost",icon:"⚖️",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Balancing means equal atoms on both sides",content:"In a chemical reaction, atoms rearrange but none appear or vanish. A balanced equation has the same number of each kind of atom on the left (before the reaction) and on the right (after it). Numbers written in front of a formula, called coefficients, multiply every atom count inside it: 2H2O means 4 hydrogen atoms and 2 oxygen atoms in total."},{type:"multiple_choice",question:"H2 + O2 -> H2O. Is this equation balanced?",options:["Yes, both sides match","No, the right side has too few oxygen atoms","No, the left side has too few hydrogen atoms"],correct:1,explanation:"Left: 2 H, 2 O. Right: 2 H, 1 O. Oxygen does not match, so it is not balanced."},{type:"translate",question:"Balance: 2H2 + O2 -> ?H2O. What coefficient goes before H2O?",correct:"2",explanation:"Left has 4 H and 2 O. Putting 2 in front of H2O gives 4 H and 2 O on the right too: balanced."},{type:"multiple_choice",question:"Why must an equation be balanced?",options:["To make it look neat","Because atoms are neither created nor destroyed in a reaction","Because chemists prefer even numbers"],correct:1,explanation:"Conservation of matter: every atom present before the reaction must still be present after it, just rearranged."}]},{id:"chem-l4",title:"Burning methane",icon:"🔥",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"CH4 + 2O2 -> CO2 + 2H2O",content:"When methane gas burns in oxygen, it produces carbon dioxide and water. The balanced equation is CH4 + 2O2 -> CO2 + 2H2O. Check it: left side has 1 carbon, 4 hydrogen, 4 oxygen (2 x O2 = 4 O); right side has 1 carbon (in CO2), 4 hydrogen (in 2H2O), and 4 oxygen (2 in CO2 plus 2 in 2H2O). Every count matches."},{type:"multiple_choice",question:"In the balanced equation CH4 + 2O2 -> CO2 + 2H2O, how many oxygen atoms are on the left side?",options:["2","4","3"],correct:1,explanation:"2O2 means two molecules of O2, each with 2 oxygen atoms: 2 x 2 = 4 oxygen atoms."},{type:"multiple_choice",question:"How many hydrogen atoms are on the right side, in 2H2O?",options:["2","4","6"],correct:1,explanation:"2H2O means two water molecules, each with 2 hydrogen atoms: 2 x 2 = 4 hydrogen atoms."},{type:"translate",question:"Methane burns as CH4 + ?O2 -> CO2 + 2H2O. What coefficient goes before O2?",correct:"2",explanation:"The right side needs 4 oxygen atoms total (2 in CO2, 2 in 2H2O); 2O2 supplies exactly 4."}]}]},{id:"chem-b1",title:"Review",tier:"B1",unlocked:!0,lessons:[{id:"chem-l5",title:"Matter and Reaction: review",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"The symbol Cl stands for",options:["calcium","chlorine","carbon"],correct:1,explanation:"Cl is chlorine."},{type:"multiple_choice",question:"H2O means",options:["one hydrogen, two oxygen atoms","two hydrogen, one oxygen atom","two hydrogen, two oxygen atoms"],correct:1,explanation:"The subscript 2 after H gives two hydrogen atoms; O with no subscript is one oxygen atom."},{type:"multiple_choice",question:"A balanced chemical equation must have",options:["the same number of molecules on each side","the same number of each kind of atom on each side","the same number of elements listed on each side"],correct:1,explanation:"Atoms are conserved: their counts, not the number of molecules, must match on both sides."},{type:"multiple_choice",question:"In 2H2 + O2 -> 2H2O, how many hydrogen atoms are on the left?",options:["2","4","8"],correct:1,explanation:"2H2 means two H2 molecules, each with 2 hydrogen atoms: 2 x 2 = 4."},{type:"multiple_choice",question:"CH4 + 2O2 -> CO2 + 2H2O is balanced because",options:["both sides have 1 carbon, 4 hydrogen and 4 oxygen atoms","both sides have exactly 3 molecules","methane and oxygen are the same substance"],correct:0,explanation:"Counting each atom type on both sides gives 1 C, 4 H, 4 O -- matching, so it is balanced."},{type:"translate",question:"Salt is made of one sodium atom and one chlorine atom. Write its formula.",correct:"NaCl",acceptable:["NaCl","nacl"],explanation:"One Na and one Cl gives NaCl."}]}]}]},"physics-fields":{title:"Fields and Waves",color:"#0891b2",sections:[{id:"pf2-a1",title:"Electric circuits",tier:"A1",unlocked:!0,lessons:[{id:"pf2-l1",title:"Ohm's law",icon:"⚡",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"V = I x R",content:"Ohm's law relates voltage (V, in volts), current (I, in amps) and resistance (R, in ohms): V = I x R. More voltage pushes more current through the same resistance; more resistance means less current for the same voltage."},{type:"multiple_choice",question:"A circuit has a current of 2 amps through a resistance of 5 ohms. What is the voltage?",options:["7 volts","10 volts","2.5 volts"],correct:1,explanation:"V = I x R = 2 x 5 = 10 volts."},{type:"translate",question:"A 12 volt battery drives current through a 4 ohm resistor. How many amps flow? (V = I x R, so I = V / R)",correct:"3",explanation:"I = V / R = 12 / 4 = 3 amps."},{type:"multiple_choice",question:"If resistance doubles while voltage stays the same, current",options:["doubles","halves","stays the same"],correct:1,explanation:"I = V / R: with V fixed, doubling R halves I."}]},{id:"pf2-l2",title:"Series and parallel",icon:"🔌",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"One path or many",content:"In a series circuit, components sit one after another on a single path, so the same current flows through all of them, and if one breaks the whole circuit stops. In a parallel circuit, components sit on separate branches, so current can keep flowing through the others even if one branch breaks."},{type:"multiple_choice",question:"In a series circuit of three bulbs, if one bulb burns out, what happens to the others?",options:["They keep glowing normally","They also go out, since the single path is broken","They glow brighter"],correct:1,explanation:"Series components share one path; breaking any point in that path stops current everywhere on it."},{type:"multiple_choice",question:"Why are household lights usually wired in parallel rather than series?",options:["Parallel wiring is cheaper","So one broken bulb does not turn off every other light","Parallel wiring uses less current"],correct:1,explanation:"Parallel branches are independent: a fault in one does not interrupt current to the others."}]}]},{id:"pf2-a2",title:"Waves and light",tier:"A2",unlocked:!0,lessons:[{id:"pf2-l3",title:"Wave speed",icon:"🌊",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"speed = wavelength x frequency",content:"A wave’s speed equals its wavelength (the distance between two peaks, in metres) times its frequency (how many waves pass a point per second, in hertz): v = wavelength x f. For a fixed speed, a longer wavelength means a lower frequency, and a shorter wavelength means a higher frequency."},{type:"translate",question:"A wave has wavelength 2 metres and frequency 5 hertz. What is its speed in metres per second? (v = wavelength x f)",correct:"10",explanation:"v = 2 x 5 = 10 metres per second."},{type:"multiple_choice",question:"A sound wave travels at 340 m/s with wavelength 0.5 m. What is its frequency? (f = v / wavelength)",options:["170 Hz","680 Hz","85 Hz"],correct:1,explanation:"f = v / wavelength = 340 / 0.5 = 680 hertz."},{type:"multiple_choice",question:"If a wave’s speed stays fixed and its frequency increases, its wavelength",options:["increases","decreases","stays the same"],correct:1,explanation:"v = wavelength x f is fixed; a larger f requires a smaller wavelength to keep the product the same."}]},{id:"pf2-l4",title:"Reflection and refraction",icon:"🔮",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Bouncing back or bending through",content:"Reflection is light bouncing off a surface, like a mirror, at an angle equal to the angle it arrived at. Refraction is light bending as it passes from one material into another, such as air into water, because light changes speed between the two materials."},{type:"multiple_choice",question:"A straw in a glass of water looks bent at the water’s surface. This is because of",options:["reflection","refraction","absorption"],correct:1,explanation:"Light bends as it moves from water into air (or back), because its speed changes between the two materials -- refraction."},{type:"multiple_choice",question:"Light hitting a flat mirror at 30 degrees from the surface leaves at",options:["30 degrees, on the other side of the normal","60 degrees","0 degrees"],correct:0,explanation:"Reflection: the angle of incidence equals the angle of reflection, measured from the normal (perpendicular to the surface)."}]}]},{id:"pf2-b1",title:"Review",tier:"B1",unlocked:!0,lessons:[{id:"pf2-l5",title:"Fields and Waves: review",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"Ohm's law states that",options:["V = I x R","V = I / R","V = I + R"],correct:0,explanation:"V = I x R is Ohm's law: voltage equals current times resistance."},{type:"multiple_choice",question:"A circuit has 3 amps flowing through a 4 ohm resistor. The voltage is",options:["7 volts","12 volts","1.33 volts"],correct:1,explanation:"V = I x R = 3 x 4 = 12 volts."},{type:"multiple_choice",question:"In a parallel circuit, if one branch breaks,",options:["every branch stops","the other branches keep carrying current","the voltage disappears everywhere"],correct:1,explanation:"Parallel branches are independent paths; a break in one does not interrupt the others."},{type:"multiple_choice",question:"Wave speed equals",options:["wavelength x frequency","wavelength / frequency","wavelength + frequency"],correct:0,explanation:"v = wavelength x f."},{type:"multiple_choice",question:"A wave of wavelength 3 m and frequency 4 Hz has a speed of",options:["7 m/s","12 m/s","0.75 m/s"],correct:1,explanation:"v = wavelength x f = 3 x 4 = 12 m/s."},{type:"multiple_choice",question:"A bent-looking straw in a glass of water is an example of",options:["reflection","refraction","diffraction only"],correct:1,explanation:"Light bends when it changes speed passing between air and water -- refraction."}]}]}]},"astronomy-basics":{title:"Astronomy",color:"#4338ca",sections:[{id:"astro-a1",title:"The solar system",tier:"A1",unlocked:!0,lessons:[{id:"astro-l1",title:"Order of the planets",icon:"🪐",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Eight planets, in order from the sun",content:"The eight planets, from nearest the sun to farthest, are: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. The four inner planets (Mercury, Venus, Earth, Mars) are small and rocky; the four outer ones (Jupiter, Saturn, Uranus, Neptune) are much larger and made mostly of gas."},{type:"multiple_choice",question:"Which planet is closest to the sun?",options:["Venus","Mercury","Earth"],correct:1,explanation:"Mercury orbits closest to the sun of the eight planets."},{type:"multiple_choice",question:"Which planet comes right after Earth, moving outward from the sun?",options:["Venus","Mars","Jupiter"],correct:1,explanation:"The order outward is Mercury, Venus, Earth, Mars -- Mars follows Earth."},{type:"multiple_choice",question:"Which is the largest planet in the solar system?",options:["Saturn","Jupiter","Neptune"],correct:1,explanation:"Jupiter is by far the largest planet, more massive than all the others combined."},{type:"word_arrange",question:"Order these four planets from the sun outward",words:["Mercury","Venus","Earth","Mars"],correct:[0,1,2,3]}]},{id:"astro-l2",title:"Day, night and seasons",icon:"🌞",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Tilt, not distance, makes the seasons",content:"Day and night happen because Earth spins on its axis, turning each side toward and away from the sun roughly every 24 hours. Seasons happen because Earth’s axis is tilted: through the year, the tilt points a hemisphere more toward the sun (summer there) or more away from it (winter there). Earth’s distance from the sun barely changes and is not the cause."},{type:"multiple_choice",question:"What causes day and night?",options:["Earth orbiting the sun","Earth spinning on its own axis","The sun moving around Earth"],correct:1,explanation:"Earth’s roughly 24-hour spin turns each location toward or away from the sun, giving day and night."},{type:"multiple_choice",question:"What is the main cause of the seasons?",options:["Earth being closer to the sun in summer","The tilt of Earth’s axis, which changes which hemisphere faces the sun more directly","The moon blocking sunlight in winter"],correct:1,explanation:"It is Earth’s axial tilt, not its distance from the sun, that causes summer and winter."},{type:"multiple_choice",question:"While the northern hemisphere has summer, the southern hemisphere has",options:["summer too","winter","no season at all"],correct:1,explanation:"The tilt points the north toward the sun and the south away from it at the same time, so their seasons are opposite."}]}]},{id:"astro-a2",title:"Orbits",tier:"A2",unlocked:!0,lessons:[{id:"astro-l3",title:"Farther means slower",icon:"🌑",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Kepler's rule: farther orbits take longer",content:"A planet’s orbital period is how long it takes to go once around the sun. Kepler found that planets farther from the sun take longer to orbit it: Mercury takes about 88 days, Earth takes 1 year (about 365 days), and Neptune takes about 165 years. Both a longer path and a slower speed at that distance make the farther planet’s year much longer."},{type:"multiple_choice",question:"Which planet has the shorter orbital period: Earth or Jupiter?",options:["Earth","Jupiter","They are the same"],correct:0,explanation:"Earth, being closer to the sun, completes its orbit (1 year) far faster than distant Jupiter (about 12 years)."},{type:"multiple_choice",question:"Mercury orbits the sun in about 88 days; Earth takes about 365 days. This fits the rule that",options:["closer planets orbit faster","closer planets orbit slower","orbital period does not depend on distance"],correct:0,explanation:"Mercury, much closer to the sun than Earth, has a much shorter orbital period -- closer means faster around."},{type:"multiple_choice",question:"Neptune, the farthest planet, has an orbital period of about",options:["165 days","16 years","165 years"],correct:2,explanation:"Neptune takes roughly 165 Earth years to complete one orbit, far longer than any inner planet."}]},{id:"astro-l4",title:"The moon and its phases",icon:"🌑",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Phases come from changing sunlight angle, not shadows",content:"The moon does not make its own light; it reflects sunlight. As it orbits Earth roughly every month, the angle between the sun, moon and Earth changes, so we see different fractions of its sunlit half: full moon (fully lit side facing us), new moon (lit side facing away), and the crescents and quarters in between."},{type:"multiple_choice",question:"Why does the moon seem to change shape over about a month?",options:["The moon’s actual shape changes","We see different amounts of its sunlit half as its position relative to the sun and Earth changes","Earth’s shadow covers it every night"],correct:1,explanation:"The moon is always half-lit by the sun; the phase is just how much of that lit half faces Earth from our viewpoint."},{type:"multiple_choice",question:"At a new moon, what are we seeing?",options:["The fully sunlit side of the moon","Mostly the unlit side, since the sunlit side faces away from Earth","The moon is not in the sky at all"],correct:1,explanation:"At new moon the sunlit half faces the sun, away from Earth, so the side we see is mostly unlit."}]}]},{id:"astro-b1",title:"Review",tier:"B1",unlocked:!0,lessons:[{id:"astro-l5",title:"Astronomy: review",icon:"🏆",xp:150,unlocked:!0,type:"test",work:"control",exercises:[{type:"multiple_choice",question:"In order from the sun, the first three planets are",options:["Venus, Mercury, Earth","Mercury, Venus, Earth","Earth, Venus, Mercury"],correct:1,explanation:"The order outward from the sun is Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune."},{type:"multiple_choice",question:"The largest planet in the solar system is",options:["Saturn","Jupiter","Earth"],correct:1,explanation:"Jupiter is the largest planet by far."},{type:"multiple_choice",question:"Day and night are caused by",options:["Earth spinning on its axis","Earth orbiting the sun","The moon blocking the sun"],correct:0,explanation:"Earth’s roughly 24-hour spin, not its yearly orbit, causes day and night."},{type:"multiple_choice",question:"Seasons are mainly caused by",options:["Earth’s changing distance from the sun","the tilt of Earth’s axis","the phases of the moon"],correct:1,explanation:"The axial tilt, not distance from the sun, drives the seasons."},{type:"multiple_choice",question:"A planet farther from the sun has an orbital period that is generally",options:["shorter","longer","unrelated to distance"],correct:1,explanation:"Kepler's rule: farther planets take longer to complete one orbit -- Neptune takes about 165 years versus Earth's 1."},{type:"multiple_choice",question:"The moon’s phases occur because",options:["the moon’s shape physically changes","we see different amounts of its sunlit half as it orbits Earth","the moon sometimes stops shining"],correct:1,explanation:"The moon always has one sunlit half; the phase is how much of that half faces Earth."}]}]}]},programming:{title:"Strategic Programming",color:"#22d3ee",sections:[{id:"prog-a1",title:"Logic & Loops",tier:"A1",unlocked:!0,lessons:[{id:"prog-l1",title:"The If Statement",icon:"❓",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Conditionals",content:'An "if" statement checks a condition before executing code.'},{type:"multiple_choice",question:"Result of if(true) { print(1) }?",options:["0","1","Error"],correct:1}]}]},{id:"prog-a2",title:"Data Structures",tier:"A2",unlocked:!0,lessons:[{id:"prog-l2",title:"Arrays & Lists",icon:"📋",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Storing Data",content:"Arrays store a collection of items at contiguous memory locations."},{type:"multiple_choice",question:"First index of an array?",options:["0","1"],correct:0}]}]},{id:"prog-b1",title:"Algorithms & Complexity",tier:"B1",unlocked:!0,lessons:[{id:"prog-l3",title:"Binary Search",icon:"🔍",xp:60,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Efficient Search",content:"Binary search finds an item in a sorted list by repeatedly halving the search space."},{type:"multiple_choice",question:"What is the time complexity of linear search on a list of n items?",options:["O(1)","O(n)","O(log n)"],correct:1,explanation:"Linear search may check every item once, in the worst case n comparisons: O(n)."},{type:"multiple_choice",question:"What is the time complexity of binary search on a sorted list of n items?",options:["O(n)","O(log n)","O(n^2)"],correct:1,explanation:"Each step of binary search halves the remaining range, giving O(log n)."},{type:"multiple_choice",question:"Binary search requires the list to be",options:["sorted","short","unique values only"],correct:0,explanation:"Halving only discards the correct half when the list is sorted; on an unsorted list the trick fails."}]}]}]},"programming-basics":{title:"Programming Foundations",color:"#22d3ee",sections:[{id:"pf-a1",title:"What a program is",tier:"A1",unlocked:!0,lessons:[{id:"pf-l1",title:"Instructions and order",icon:"📜",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"A program is a list of steps",content:"A computer does exactly what it is told, in the order it is told. Nothing is guessed, nothing is skipped. Writing a program means writing that list precisely enough for a machine to follow it without asking you anything."},{type:"multiple_choice",question:"Making tea: (1) pour the water (2) boil the water (3) add the teabag. What is wrong?",options:["Nothing is wrong","The order is wrong","A step is missing"],correct:1,explanation:"All three steps are present, but pouring before boiling gives cold tea. Order carries meaning."},{type:"multiple_choice",question:"Why must instructions be exact?",options:["Computers are slow","A computer cannot guess what you meant","Programs are long"],correct:1,explanation:"A person fills gaps from experience. A machine has none: an unclear step becomes an error or a wrong result."},{type:"word_arrange",question:"Order the steps: opening a door with a key",words:["take out the key","put it in the lock","turn the key","pull the handle"],correct:[0,1,2,3]}]},{id:"pf-l1b",title:"Values and names",icon:"📦",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"A name holds a value",content:"A program keeps values: a number, a piece of text, a yes-or-no answer. Each gets a name so later steps can use it. Naming is not decoration — it is how one step hands its result to the next."},{type:"multiple_choice",question:"price = 10, then price = 25. What is in price now?",options:["10","25","both"],correct:1,explanation:"Assignment replaces. A name holds one value at a time; the old one is gone."},{type:"code_output",question:"What is printed?\n\na = 3\nb = 4\na = b\nprint(a + b)",options:["7","8","6"],correct:1,explanation:"After a = b both names hold 4, so the sum is 8. Assignment copies the value; it does not tie the names together."},{type:"multiple_choice",question:"Best name for the count of unread letters?",options:["x","unread_count","n1"],correct:1,explanation:"A name is read far more often than written. Your own code from last month is someone else’s code."}]},{id:"pf-l1c",title:"Kinds of values",icon:"🔣",xp:25,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Numbers and text are different things",content:'The number 12 and the text "12" look the same on screen and behave differently. Numbers add up; text joins end to end. Many beginner bugs are one kind quietly used where the other was meant.'},{type:"code_output",question:'What is printed?\n\nprint("2" + "3")',options:["5","23","an error"],correct:1,explanation:"Two pieces of text are joined: 23. For 5 you need numbers: 2 + 3."},{type:"multiple_choice",question:"A phone number is best stored as",options:["a number","text"],correct:1,explanation:"Phone numbers are never added, and a leading zero would be lost in a number. That makes them text."}]}]},{id:"pf-a2",title:"Choice, repetition, structure",tier:"A2",unlocked:!0,lessons:[{id:"pf-l2",title:"Conditions",icon:"🔀",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"A fork in the road",content:"A condition asks a yes-or-no question and runs one branch or the other. This is where a program stops being a fixed list and starts responding to what it is given."},{type:"code_output",question:'age = 15. What is printed?\n\nif age >= 18:\n    print("adult")\nelse:\n    print("minor")',options:["adult","minor","both"],correct:1,explanation:"15 >= 18 is false, so only the else branch runs. Exactly one branch runs, never both."},{type:"multiple_choice",question:'When is "it is raining AND I have an umbrella" true?',options:["When at least one holds","Only when both hold","Always"],correct:1,explanation:"AND needs both; at least one is OR. Confusing them is a common source of wrong conditions."},{type:"multiple_choice",question:"Which lets in ages 14 to 18 inclusive?",options:["age > 14 and age < 18","age >= 14 and age <= 18","age >= 14 or age <= 18"],correct:1,explanation:"Inclusive bounds need >= and <=. The third is true for every age, since any number satisfies one half."}]},{id:"pf-l2b",title:"Loops",icon:"🔄",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Say it once, do it many times",content:"A loop repeats steps while something stays true, or once per item in a list. The programmer’s job is to be sure it ends: a loop whose condition never turns false runs forever."},{type:"code_output",question:"What is printed?\n\ntotal = 0\nfor n in [1, 2, 3, 4]:\n    total = total + n\nprint(total)",options:["4","10","24"],correct:1,explanation:"The total grows 1, 3, 6, 10. This accumulator pattern appears in almost every program."},{type:"code_output",question:'How many times is the line printed?\n\ni = 0\nwhile i < 3:\n    print("hi")\n    i = i + 1',options:["2","3","forever"],correct:1,explanation:"i takes 0, 1, 2 and then the condition fails. Remove i = i + 1 and it would indeed run forever."},{type:"multiple_choice",question:"What makes a loop never stop?",options:["Too many items","Nothing inside moves the condition towards false","A condition false at the start"],correct:1,explanation:"If the body never changes what the condition tests, nothing else will."}]},{id:"pf-l2c",title:"Lists",icon:"📋",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Many values under one name",content:"A list holds values in order under a single name, and each has a position. Counting starts at zero: the first item is at position 0. That is a convention, and forgetting it is the most common off-by-one mistake."},{type:"multiple_choice",question:"First position in a list?",options:["0","1"],correct:0,explanation:"Position is an offset from the start, and the first item is zero steps in."},{type:"code_output",question:'What is printed?\n\nnames = ["ann", "bob", "cid"]\nprint(names[1])',options:["ann","bob","cid"],correct:1,explanation:"Position 1 is the second item, because positions start at 0."},{type:"code_output",question:'A list of 3 items. What happens?\n\nnames = ["ann", "bob", "cid"]\nprint(names[3])',options:["cid","an error","nothing"],correct:1,explanation:"Valid positions are 0, 1, 2. Position 3 is past the end — the classic off-by-one."}]},{id:"pf-l2d",title:"Functions",icon:"🧩",xp:45,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Name a piece of work once",content:"A function is a named piece of work: you hand it values, it hands back a result. It exists so an idea is written once, tested once and fixed in one place. A program without functions repeats itself, and repetition is where errors hide."},{type:"code_output",question:"What is printed?\n\ndef double(x):\n    return x * 2\n\nprint(double(5) + double(2))",options:["14","10","7"],correct:0,explanation:"double(5) is 10 and double(2) is 4, so 14. The function runs once per call."},{type:"multiple_choice",question:"Why move repeated steps into a function?",options:["The program runs faster","One fix applies everywhere it is used","It uses less memory"],correct:1,explanation:"The gain is maintenance, not speed. The same steps copied five times means five fixes — and four forgotten ones."},{type:"word_arrange",question:"Order the parts of a function call",words:["give it values","it does the work","it returns a result","the result is used"],correct:[0,1,2,3]}]}]},{id:"pf-b1",title:"Thinking like a programmer",tier:"B1",unlocked:!0,lessons:[{id:"pf-l3",title:"Errors and finding them",icon:"🐛",xp:60,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Wrong is the normal state of new code",content:"Errors come in two kinds. The program refuses to run — a typo, a missing bracket — and the machine tells you where. Or it runs and gives a wrong answer, and nobody tells you anything. The second kind is the real work: you check what you believe against what is actually there."},{type:"code_output",question:"The average of 2 and 4 should be 3. What is printed?\n\nprint(2 + 4 / 2)",options:["3","4","3.0"],correct:1,explanation:"Division runs before addition: 2 + 2 = 4. It needs brackets: (2 + 4) / 2. The program was never broken, only wrong."},{type:"multiple_choice",question:"It runs but the answer is wrong. First step?",options:["Rewrite from scratch","Look at the actual values at each step","Try random changes"],correct:1,explanation:"A wrong answer means some step differs from your assumption. Looking at real values finds the gap; guessing hides it."},{type:"multiple_choice",question:"It works on 5 items and fails on an empty list. That means",options:["The computer is faulty","You never considered the empty case","Empty lists are not allowed"],correct:1,explanation:"Edge cases — empty, one item, the largest — are where assumptions show. Think of them before the user does."}]},{id:"pf-l3b",title:"From idea to steps",icon:"🧭",xp:60,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"An algorithm is a plan that always ends",content:"Before writing code you settle three things: what you are given, what you want, and the steps between. A plan that may never finish is not an algorithm. Languages differ; this part does not."},{type:"word_arrange",question:"Order the steps: find the largest number in a list",words:["take the first number as the largest so far","look at the next number","if it is bigger, it becomes the largest so far","when the list ends, report the largest"],correct:[0,1,2,3]},{type:"multiple_choice",question:"Looking up a word by opening the middle and halving each time is fast because",options:["Dictionaries are small","Each step discards half of what is left","Only dictionaries are sorted"],correct:1,explanation:"This is binary search: a thousand pages take about ten steps, because each step halves the remainder."},{type:"multiple_choice",question:"What is true of every algorithm?",options:["It is written in a specific language","It ends after a finite number of steps","It is short"],correct:1,explanation:"Termination is part of the definition. A plan that runs forever solves nothing, however elegant."}]}]}]},chess:{title:"Chess Mastery",color:"#a855f7",sections:[{id:"chess-a1",title:"Board Control",tier:"A1",unlocked:!0,lessons:[{id:"chess-l1",title:"The Center Square",icon:"🏰",xp:30,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Opening Strategy",content:"Control the four central squares to dominate the board."},{type:"multiple_choice",question:"Most important squares?",options:["Edges","Corners","Center"],correct:2}]}]},{id:"chess-a2",title:"Tactics Arena",tier:"A2",unlocked:!0,lessons:[{id:"chess-l2",title:"The Fork",icon:"🍴",xp:50,unlocked:!0,work:"classwork",exercises:[{type:"lecture",question:"Tactical Patterns",content:"A fork occurs when one piece attacks two or more enemy pieces simultaneously."},{type:"multiple_choice",question:"Best piece for a fork?",options:["Pawn","Knight","King"],correct:1}]}]}]},french:{title:"French Journey",color:"#3b82f6",sections:[{id:"french-a1-1",title:"First words",tier:"A1",unlocked:!0,lessons:[{id:"french-a1-greetings",title:"Greetings",icon:"👋",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Greetings",content:"Bonjour is for the day and bonsoir for the evening; salut is only for people you know. French adds s'il vous plaît and merci far more readily than English adds please and thanks -- leaving them out sounds abrupt."},{type:"multiple_choice",question:"What does «bonjour» mean?",options:["hello / good morning","thank you","good evening"],correct:0,explanation:"«bonjour» means “hello / good morning”."},{type:"multiple_choice",question:"What does «salut» mean?",options:["please","hi","yes"],correct:1,explanation:"«salut» means “hi”."},{type:"multiple_choice",question:"What does «non» mean?",options:["hello / good morning","thank you","no"],correct:2,explanation:"«non» means “no”."},{type:"translate",question:"Write in French: “thank you”",correct:"merci",explanation:"“thank you” is «merci»."},{type:"translate",question:"Write in French: “goodbye”",correct:"au revoir",explanation:"“goodbye” is «au revoir»."}]},{id:"french-a1-introductions",title:"Who I am",icon:"🧑",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Who I am",content:"The verb to be changes with the person: je suis, tu es, il est, elle est, nous sommes. Tu is for friends and children; with a stranger you say vous. Je m'appelle literally means I call myself."},{type:"multiple_choice",question:"What does «je suis» mean?",options:["I am","you are","he is"],correct:0,explanation:"«je suis» means “I am”."},{type:"multiple_choice",question:"What does «elle est» mean?",options:["we are","she is","my name is"],correct:1,explanation:"«elle est» means “she is”."},{type:"multiple_choice",question:"What does «enchanté» mean?",options:["I am","you are","nice to meet you"],correct:2,explanation:"«enchanté» means “nice to meet you”."},{type:"translate",question:"Write in French: “I am”",correct:"je suis",explanation:"“I am” is «je suis»."},{type:"translate",question:"Write in French: “we are”",correct:"nous sommes",explanation:"“we are” is «nous sommes»."}]},{id:"french-a1-numbers",title:"Numbers 1-10",icon:"🔢",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers 1-10",content:"Un, deux, trois. The final consonant is usually silent: deux sounds like deu, trois like trwa. Un also means a, so un chat is both one cat and a cat."},{type:"multiple_choice",question:"What does «un» mean?",options:["one","two","three"],correct:0,explanation:"«un» means “one”."},{type:"multiple_choice",question:"What does «six» mean?",options:["seven","six","eight"],correct:1,explanation:"«six» means “six”."},{type:"multiple_choice",question:"What does «dix» mean?",options:["one","two","ten"],correct:2,explanation:"«dix» means “ten”."},{type:"translate",question:"Write in French: “two”",correct:"deux",explanation:"“two” is «deux»."},{type:"translate",question:"Write in French: “five”",correct:"cinq",explanation:"“five” is «cinq»."}]}]},{id:"french-a1-2",title:"People and things",tier:"A1",unlocked:!0,lessons:[{id:"french-a1-family",title:"Family",icon:"👪",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Family",content:"Every French noun is masculine or feminine, and the word for the shows it: le père, la mère. Learn the noun together with its le or la -- the gender cannot be guessed from the meaning."},{type:"multiple_choice",question:"What does «la mère» mean?",options:["the mother","the father","the brother"],correct:0,explanation:"«la mère» means “the mother”."},{type:"multiple_choice",question:"What does «la sœur» mean?",options:["the son","the sister","the daughter"],correct:1,explanation:"«la sœur» means “the sister”."},{type:"multiple_choice",question:"What does «les parents» mean?",options:["the mother","the father","the parents"],correct:2,explanation:"«les parents» means “the parents”."},{type:"translate",question:"Write in French: “the father”",correct:"le père",explanation:"“the father” is «le père»."},{type:"translate",question:"Write in French: “the brother”",correct:"le frère",explanation:"“the brother” is «le frère»."}]},{id:"french-a1-food",title:"Food and drink",icon:"🍞",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Food and drink",content:"Before a vowel le and la shorten to l': l'eau, not la eau. With food you usually say du, de la or de l' -- some -- rather than naming the thing bare: je veux du pain, I want some bread."},{type:"multiple_choice",question:"What does «le pain» mean?",options:["the bread","the water","the milk"],correct:0,explanation:"«le pain» means “the bread”."},{type:"multiple_choice",question:"What does «le fromage» mean?",options:["the apple","the cheese","the coffee"],correct:1,explanation:"«le fromage» means “the cheese”."},{type:"multiple_choice",question:"What does «le thé» mean?",options:["the bread","the water","the tea"],correct:2,explanation:"«le thé» means “the tea”."},{type:"translate",question:"Write in French: “the bread”",correct:"le pain",explanation:"“the bread” is «le pain»."},{type:"translate",question:"Write in French: “the milk”",correct:"le lait",explanation:"“the milk” is «le lait»."}]},{id:"french-a1-have",title:"I have",icon:"📚",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"I have",content:"To have: j'ai, tu as, il a, nous avons. Je shortens to j' before a vowel. French uses avoir where English uses to be for age and hunger: j'ai faim is literally I have hunger."},{type:"multiple_choice",question:"What does «j'ai» mean?",options:["I have","you have","he has"],correct:0,explanation:"«j'ai» means “I have”."},{type:"multiple_choice",question:"What does «un livre» mean?",options:["a house","a book","a cat"],correct:1,explanation:"«un livre» means “a book”."},{type:"multiple_choice",question:"What does «un chien» mean?",options:["I have","you have","a dog"],correct:2,explanation:"«un chien» means “a dog”."},{type:"translate",question:"Write in French: “I have”",correct:"j'ai",explanation:"“I have” is «j'ai»."},{type:"translate",question:"Write in French: “a cat”",correct:"un chat",explanation:"“a cat” is «un chat»."}]}]},{id:"french-a1-3",title:"Getting around",tier:"A1",unlocked:!0,lessons:[{id:"french-a1-questions",title:"Questions and directions",icon:"❓",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Questions and directions",content:"Question words start the sentence: où est la gare ? -- where is the station? In speech a plain statement with a rising voice is already a question: tu viens? À gauche and à droite are all you need to follow directions."},{type:"multiple_choice",question:"What does «où» mean?",options:["where","when","how"],correct:0,explanation:"«où» means “where”."},{type:"multiple_choice",question:"What does «combien» mean?",options:["who","how much","to the left"],correct:1,explanation:"«combien» means “how much”."},{type:"multiple_choice",question:"What does «à droite» mean?",options:["where","when","to the right"],correct:2,explanation:"«à droite» means “to the right”."},{type:"translate",question:"Write in French: “where”",correct:"où",explanation:"“where” is «où»."},{type:"translate",question:"Write in French: “to the right”",correct:"à droite",explanation:"“to the right” is «à droite»."}]},{id:"french-a1-days",title:"Days and time",icon:"📅",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Days and time",content:"Days are not capitalised in French, and the week starts on lundi. Le lundi means on Mondays, every week; lundi alone means this Monday."},{type:"multiple_choice",question:"What does «lundi» mean?",options:["Monday","Tuesday","Wednesday"],correct:0,explanation:"«lundi» means “Monday”."},{type:"multiple_choice",question:"What does «samedi» mean?",options:["Sunday","Saturday","today"],correct:1,explanation:"«samedi» means “Saturday”."},{type:"multiple_choice",question:"What does «hier» mean?",options:["Monday","Tuesday","yesterday"],correct:2,explanation:"«hier» means “yesterday”."},{type:"translate",question:"Write in French: “tomorrow”",correct:"demain",explanation:"“tomorrow” is «demain»."},{type:"translate",question:"Write in French: “Monday”",correct:"lundi",explanation:"“Monday” is «lundi»."}]}]}]},"french-a2":{title:"French Journey: A2",color:"#1d4ed8",sections:[{id:"french-a2-1",title:"Out and about",tier:"A2",unlocked:!0,lessons:[{id:"french-a2-directions",title:"Asking for directions",icon:"🧭",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Asking for directions",content:"Pardon, où est la gare, s'il vous plaît ? -- excuse me, where is the station, please? Tout droit is straight ahead, à gauche is to the left, à droite is to the right. C'est loin ? -- is it far? C'est à cinq minutes -- it is five minutes away."},{type:"multiple_choice",question:"What does «tout droit» mean?",options:["straight ahead","to the left","very far"],correct:0,explanation:"«tout droit» means “straight ahead”."},{type:"multiple_choice",question:"What does «c'est loin ?» mean?",options:["where is it?","is it far?","is it open?"],correct:1,explanation:"«c'est loin ?» means “is it far?”."},{type:"multiple_choice",question:"What does «au coin de la rue» mean?",options:["at the corner of the street","at the end of the road","next to the station"],correct:0,explanation:"«au coin de la rue» means “at the corner of the street”."},{type:"translate",question:"Write in French: “Where is the station, please?”",correct:"Où est la gare, s'il vous plaît ?",acceptable:["Ou est la gare, s'il vous plait ?","Où est la gare s'il vous plait ?"],explanation:"“Where is the station, please?” is «Où est la gare, s'il vous plaît ?»."},{type:"translate",question:"Write in French: “to the right”",correct:"à droite",explanation:"“to the right” is «à droite»."},{type:"translate",question:"Write in French: “Is it far?”",correct:"C'est loin ?",explanation:"“Is it far?” is «C'est loin ?»."}]},{id:"french-a2-restaurant",title:"Ordering food",icon:"🍽️",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Ordering food",content:"Je voudrais... is politer than je veux for ordering: je voudrais un café, s'il vous plaît -- I would like a coffee, please. L'addition, s'il vous plaît asks for the bill. Vous avez choisi ? -- have you decided? -- is what a waiter asks; you answer oui, je vais prendre... -- yes, I will have..."},{type:"multiple_choice",question:"What does «je voudrais» mean?",options:["I want","I would like","I have"],correct:1,explanation:"«je voudrais» means “I would like”."},{type:"multiple_choice",question:"What does «l'addition, s'il vous plaît» mean?",options:["the menu, please","the bill, please","some water, please"],correct:1,explanation:"«l'addition, s'il vous plaît» means “the bill, please”."},{type:"multiple_choice",question:"What does «je vais prendre» mean?",options:["I am going to have","I have already had","I do not want"],correct:0,explanation:"«je vais prendre» means “I am going to have”."},{type:"translate",question:"Write in French: “I would like a coffee, please.”",correct:"Je voudrais un café, s'il vous plaît.",acceptable:["Je voudrais un cafe, s'il vous plait."],explanation:"“I would like a coffee, please.” is «Je voudrais un café, s'il vous plaît.»."},{type:"translate",question:"Write in French: “the bill”",correct:"l'addition",explanation:"“the bill” is «l'addition»."},{type:"translate",question:"Write in French: “I will have the fish.”",correct:"Je vais prendre le poisson.",explanation:"“I will have the fish.” is «Je vais prendre le poisson.»."}]},{id:"french-a2-shopping",title:"Shopping phrases",icon:"🛍️",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Shopping phrases",content:"Combien ça coûte ? -- how much does it cost? C'est trop cher -- that is too expensive. Je fais juste un tour -- I am just looking -- turns away a shop assistant politely. Vous avez ceci en plus grand ? -- do you have this in a bigger size?"},{type:"multiple_choice",question:"What does «combien ça coûte ?» mean?",options:["what colour is it?","how much does it cost?","is it open?"],correct:1,explanation:"«combien ça coûte ?» means “how much does it cost?”."},{type:"multiple_choice",question:"What does «c'est trop cher» mean?",options:["it is too big","that is too expensive","I like it"],correct:1,explanation:"«c'est trop cher» means “that is too expensive”."},{type:"multiple_choice",question:"What does «je fais juste un tour» mean?",options:["I am just looking","I will buy it","I need help"],correct:0,explanation:"«je fais juste un tour» means “I am just looking”."},{type:"translate",question:"Write in French: “How much does it cost?”",correct:"Combien ça coûte ?",acceptable:["Combien ca coute ?"],explanation:"“How much does it cost?” is «Combien ça coûte ?»."},{type:"translate",question:"Write in French: “That is too expensive.”",correct:"C'est trop cher.",explanation:"“That is too expensive.” is «C'est trop cher.»."},{type:"translate",question:"Write in French: “I am just looking.”",correct:"Je fais juste un tour.",explanation:"“I am just looking.” is «Je fais juste un tour.»."}]}]},{id:"french-a2-2",title:"Talking about the past: -er verbs",tier:"A2",unlocked:!0,lessons:[{id:"french-a2-passe-compose-avoir",title:"Passé composé with avoir",icon:"🕰️",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Passé composé with avoir",content:"The passé composé tells what happened: it is built from avoir in the present plus a past participle. For -er verbs the participle ends in é: manger becomes mangé. J'ai mangé -- I ate / I have eaten. Tu as mangé, il a mangé, elle a mangé, nous avons mangé, vous avez mangé, ils ont mangé, elles ont mangé."},{type:"multiple_choice",question:"What does «j'ai mangé» mean?",options:["I eat","I ate","I will eat"],correct:1,explanation:"«j'ai mangé» means “I ate”, the passé composé of manger."},{type:"multiple_choice",question:"Which form goes with «nous»?",options:["nous avons mangé","nous avez mangé","nous ont mangé"],correct:0,explanation:"«nous» takes «avons»: «nous avons mangé» -- we ate."},{type:"multiple_choice",question:"What is the past participle of «parler» (to speak)?",options:["parlé","parlant","parle"],correct:0,explanation:"-er verbs form their past participle by replacing -er with -é: parler -> parlé."},{type:"translate",question:"Write in French: “She ate.”",correct:"Elle a mangé.",explanation:"“She ate.” is «Elle a mangé.», elle + a (avoir) + mangé."},{type:"translate",question:"Write in French: “We spoke.”",correct:"Nous avons parlé.",explanation:"“We spoke.” is «Nous avons parlé.»."},{type:"translate",question:"Write in French: “They (masc.) worked.”",correct:"Ils ont travaillé.",explanation:"“They (masc.) worked.” is «Ils ont travaillé.», from travailler."}]},{id:"french-a2-passe-compose-more-er",title:"More -er verbs in the past",icon:"📖",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"More -er verbs in the past",content:"The same pattern covers every regular -er verb: regarder -> regardé, écouter -> écouté, jouer -> joué, aimer -> aimé. J'ai regardé un film -- I watched a film. Tu as écouté la radio -- you listened to the radio. Négation wraps around avoir: je n'ai pas mangé -- I did not eat."},{type:"multiple_choice",question:"What does «tu as écouté» mean?",options:["you listen","you listened","you will listen"],correct:1,explanation:"«tu as écouté» means “you listened”, from écouter."},{type:"multiple_choice",question:"What does «je n'ai pas mangé» mean?",options:["I ate","I do not eat","I did not eat"],correct:2,explanation:"«je n'ai pas mangé» means “I did not eat” -- ne...pas wraps around the avoir part."},{type:"multiple_choice",question:"What is the past participle of «jouer» (to play)?",options:["joué","jouant","joue"],correct:0,explanation:"jouer -> joué, following the regular -er pattern."},{type:"translate",question:"Write in French: “I watched a film.”",correct:"J'ai regardé un film.",explanation:"“I watched a film.” is «J'ai regardé un film.»."},{type:"translate",question:"Write in French: “You (tu) played.”",correct:"Tu as joué.",explanation:"“You (tu) played.” is «Tu as joué.»."},{type:"translate",question:"Write in French: “I did not listen.”",correct:"Je n'ai pas écouté.",explanation:"“I did not listen.” is «Je n'ai pas écouté.», ne...pas around ai."}]}]},{id:"french-a2-3",title:"Talking about the past: irregulars",tier:"A2",unlocked:!0,lessons:[{id:"french-a2-avoir-etre-past",title:"Avoir and être in the past",icon:"🔑",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Avoir and être in the past",content:"Avoir and être have irregular past participles: avoir -> eu, être -> été. Both take avoir as their helper: j'ai eu -- I had, j'ai été -- I was / I have been. J'ai eu peur -- I was afraid, literally I had fear. Il a été malade -- he was sick."},{type:"multiple_choice",question:"What is the past participle of «avoir»?",options:["eu","avu","avoir"],correct:0,explanation:"avoir has the irregular past participle eu: j'ai eu -- I had."},{type:"multiple_choice",question:"What does «j'ai été» mean?",options:["I have","I was / I have been","I am"],correct:1,explanation:"«j'ai été» is the passé composé of être: “I was / I have been”."},{type:"multiple_choice",question:"What does «j'ai eu peur» mean?",options:["I am afraid","I was afraid","I will be afraid"],correct:1,explanation:"«j'ai eu peur» means “I was afraid”, literally “I had fear”."},{type:"translate",question:"Write in French: “I had.”",correct:"J'ai eu.",explanation:"“I had.” is «J'ai eu.», from avoir."},{type:"translate",question:"Write in French: “He was sick.”",correct:"Il a été malade.",explanation:"“He was sick.” is «Il a été malade.»."},{type:"translate",question:"Write in French: “We were afraid.”",correct:"Nous avons eu peur.",explanation:"“We were afraid.” is «Nous avons eu peur.», nous + avons (avoir) + eu peur."}]},{id:"french-a2-aller-past",title:"Aller in the past: an être verb",icon:"🚶",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Aller in the past: an être verb",content:"Aller (to go) is one of the small group of verbs that take être, not avoir, as their helper -- and its past participle agrees with the subject like an adjective: je suis allé if the speaker is male, je suis allée if female. Il est allé, elle est allée, ils sont allés, elles sont allées. Nous sommes allés au marché -- we went to the market."},{type:"multiple_choice",question:"Which helper verb does «aller» use in the passé composé?",options:["avoir","être","faire"],correct:1,explanation:"aller is one of the small set of verbs that take être as their helper, not avoir."},{type:"multiple_choice",question:"What does «elle est allée» mean?",options:["she goes","she went","she will go"],correct:1,explanation:"«elle est allée» means “she went” -- the participle allée agrees with the feminine subject elle."},{type:"multiple_choice",question:"Which form is correct for a group of women, «elles»?",options:["elles sont allé","elles sont allés","elles sont allées"],correct:2,explanation:"With être-verbs the past participle agrees with the subject: elles (feminine plural) takes allées."},{type:"translate",question:"Write in French: “I went.” (speaker is male)",correct:"Je suis allé.",explanation:"“I went.” for a male speaker is «Je suis allé.» -- allé with no extra letter."},{type:"translate",question:"Write in French: “I went.” (speaker is female)",correct:"Je suis allée.",explanation:"“I went.” for a female speaker is «Je suis allée.» -- allée agrees with the feminine subject."},{type:"translate",question:"Write in French: “We went to the market.”",correct:"Nous sommes allés au marché.",explanation:"“We went to the market.” is «Nous sommes allés au marché.», nous + sommes (être) + allés."}]},{id:"french-a2-faire-past",title:"Faire in the past",icon:"🛠️",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Faire in the past",content:"Faire (to do / to make) takes avoir as its helper, like most verbs, but its past participle is irregular: fait, not the regular faisé. J'ai fait mes devoirs -- I did my homework. Qu'est-ce que tu as fait ce week-end ? -- what did you do this weekend? Nous avons fait une promenade -- we took a walk."},{type:"multiple_choice",question:"What is the past participle of «faire»?",options:["faisé","fait","fais"],correct:1,explanation:"faire has the irregular past participle fait: j'ai fait -- I did / I made."},{type:"multiple_choice",question:"What does «qu'est-ce que tu as fait ?» mean?",options:["what are you doing?","what did you do?","what will you do?"],correct:1,explanation:"«qu'est-ce que tu as fait ?» means “what did you do?”."},{type:"multiple_choice",question:"What does «j'ai fait mes devoirs» mean?",options:["I do my homework","I did my homework","I like my homework"],correct:1,explanation:"«j'ai fait mes devoirs» means “I did my homework”."},{type:"translate",question:"Write in French: “I did my homework.”",correct:"J'ai fait mes devoirs.",explanation:"“I did my homework.” is «J'ai fait mes devoirs.»."},{type:"translate",question:"Write in French: “We took a walk.”",correct:"Nous avons fait une promenade.",explanation:"“We took a walk.” is «Nous avons fait une promenade.», literally “we made a walk”."},{type:"translate",question:"Write in French: “What did you (tu) do?”",correct:"Qu'est-ce que tu as fait ?",explanation:"“What did you (tu) do?” is «Qu'est-ce que tu as fait ?»."}]}]}]},italian:{title:"Italian Voyage",color:"#22c55e",sections:[{id:"italian-a1-1",title:"First words",tier:"A1",unlocked:!0,lessons:[{id:"italian-a1-greetings",title:"Greetings",icon:"👋",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Greetings",content:"Ciao is both hello and goodbye, but only between people who know each other. With anyone else it is buongiorno by day and buonasera from late afternoon. Every letter is pronounced; there are almost no silent ones."},{type:"multiple_choice",question:"What does «ciao» mean?",options:["hi / bye","thank you","good morning"],correct:0,explanation:"«ciao» means “hi / bye”."},{type:"multiple_choice",question:"What does «buonasera» mean?",options:["please","good evening","yes"],correct:1,explanation:"«buonasera» means “good evening”."},{type:"multiple_choice",question:"What does «no» mean?",options:["hi / bye","thank you","no"],correct:2,explanation:"«no» means “no”."},{type:"translate",question:"Write in Italian: “thank you”",correct:"grazie",explanation:"“thank you” is «grazie»."},{type:"translate",question:"Write in Italian: “goodbye”",correct:"arrivederci",explanation:"“goodbye” is «arrivederci»."}]},{id:"italian-a1-introductions",title:"Who I am",icon:"🧑",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Who I am",content:"To be: io sono, tu sei, lui è, lei è, noi siamo. The pronoun is usually dropped because the verb already shows the person: sono Marco, I am Marco. Lei with a capital is also the polite you."},{type:"multiple_choice",question:"What does «io sono» mean?",options:["I am","you are","he is"],correct:0,explanation:"«io sono» means “I am”."},{type:"multiple_choice",question:"What does «lei è» mean?",options:["we are","she is","my name is"],correct:1,explanation:"«lei è» means “she is”."},{type:"multiple_choice",question:"What does «piacere» mean?",options:["I am","you are","nice to meet you"],correct:2,explanation:"«piacere» means “nice to meet you”."},{type:"translate",question:"Write in Italian: “I am”",correct:"io sono",explanation:"“I am” is «io sono»."},{type:"translate",question:"Write in Italian: “we are”",correct:"noi siamo",explanation:"“we are” is «noi siamo»."}]},{id:"italian-a1-numbers",title:"Numbers 1-10",icon:"🔢",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers 1-10",content:"Uno, due, tre. Uno changes before a noun like the word a: un libro, una casa. Double consonants are really held longer -- sette and otto are not sete and oto."},{type:"multiple_choice",question:"What does «uno» mean?",options:["one","two","three"],correct:0,explanation:"«uno» means “one”."},{type:"multiple_choice",question:"What does «sei» mean?",options:["seven","six","eight"],correct:1,explanation:"«sei» means “six”."},{type:"multiple_choice",question:"What does «dieci» mean?",options:["one","two","ten"],correct:2,explanation:"«dieci» means “ten”."},{type:"translate",question:"Write in Italian: “two”",correct:"due",explanation:"“two” is «due»."},{type:"translate",question:"Write in Italian: “five”",correct:"cinque",explanation:"“five” is «cinque»."}]}]},{id:"italian-a1-2",title:"People and things",tier:"A1",unlocked:!0,lessons:[{id:"italian-a1-family",title:"Family",icon:"👪",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Family",content:"Nouns ending in -o are usually masculine, in -a feminine: il fratello, la sorella. Padre and madre end in -e and have to be learned with their article. With one family member the article drops after my: mia madre, not la mia madre."},{type:"multiple_choice",question:"What does «la madre» mean?",options:["the mother","the father","the brother"],correct:0,explanation:"«la madre» means “the mother”."},{type:"multiple_choice",question:"What does «la sorella» mean?",options:["the son","the sister","the daughter"],correct:1,explanation:"«la sorella» means “the sister”."},{type:"multiple_choice",question:"What does «i genitori» mean?",options:["the mother","the father","the parents"],correct:2,explanation:"«i genitori» means “the parents”."},{type:"translate",question:"Write in Italian: “the father”",correct:"il padre",explanation:"“the father” is «il padre»."},{type:"translate",question:"Write in Italian: “the brother”",correct:"il fratello",explanation:"“the brother” is «il fratello»."}]},{id:"italian-a1-food",title:"Food and drink",icon:"🍞",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Food and drink",content:"Before a vowel the article becomes l': l'acqua. Caffè carries its stress on the last letter, which is why it is written with an accent. Ordering un caffè in Italy gets you an espresso."},{type:"multiple_choice",question:"What does «il pane» mean?",options:["the bread","the water","the milk"],correct:0,explanation:"«il pane» means “the bread”."},{type:"multiple_choice",question:"What does «il formaggio» mean?",options:["the apple","the cheese","the coffee"],correct:1,explanation:"«il formaggio» means “the cheese”."},{type:"multiple_choice",question:"What does «il tè» mean?",options:["the bread","the water","the tea"],correct:2,explanation:"«il tè» means “the tea”."},{type:"translate",question:"Write in Italian: “the bread”",correct:"il pane",explanation:"“the bread” is «il pane»."},{type:"translate",question:"Write in Italian: “the milk”",correct:"il latte",explanation:"“the milk” is «il latte»."}]},{id:"italian-a1-have",title:"I have",icon:"📚",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"I have",content:"To have: io ho, tu hai, lui ha, noi abbiamo. The h is silent and only there to tell ho apart from o. As in French, age and hunger use to have: ho fame, I am hungry."},{type:"multiple_choice",question:"What does «io ho» mean?",options:["I have","you have","he has"],correct:0,explanation:"«io ho» means “I have”."},{type:"multiple_choice",question:"What does «un libro» mean?",options:["a house","a book","a cat"],correct:1,explanation:"«un libro» means “a book”."},{type:"multiple_choice",question:"What does «un cane» mean?",options:["I have","you have","a dog"],correct:2,explanation:"«un cane» means “a dog”."},{type:"translate",question:"Write in Italian: “I have”",correct:"io ho",explanation:"“I have” is «io ho»."},{type:"translate",question:"Write in Italian: “a cat”",correct:"un gatto",explanation:"“a cat” is «un gatto»."}]}]},{id:"italian-a1-3",title:"Getting around",tier:"A1",unlocked:!0,lessons:[{id:"italian-a1-questions",title:"Questions and directions",icon:"❓",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Questions and directions",content:"Dove, quando, come, perché. Perché means both why and because -- the question and its answer start with the same word. Dov'è is dove è run together: dov'è la stazione?"},{type:"multiple_choice",question:"What does «dove» mean?",options:["where","when","how"],correct:0,explanation:"«dove» means “where”."},{type:"multiple_choice",question:"What does «quanto» mean?",options:["who","how much","to the left"],correct:1,explanation:"«quanto» means “how much”."},{type:"multiple_choice",question:"What does «a destra» mean?",options:["where","when","to the right"],correct:2,explanation:"«a destra» means “to the right”."},{type:"translate",question:"Write in Italian: “where”",correct:"dove",explanation:"“where” is «dove»."},{type:"translate",question:"Write in Italian: “to the right”",correct:"a destra",explanation:"“to the right” is «a destra»."}]},{id:"italian-a1-days",title:"Days and time",icon:"📅",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Days and time",content:"Weekdays from lunedì to venerdì carry the stress on the final i, hence the accent. They are not capitalised. Il lunedì means every Monday; lunedì alone means this Monday."},{type:"multiple_choice",question:"What does «lunedì» mean?",options:["Monday","Tuesday","Wednesday"],correct:0,explanation:"«lunedì» means “Monday”."},{type:"multiple_choice",question:"What does «sabato» mean?",options:["Sunday","Saturday","today"],correct:1,explanation:"«sabato» means “Saturday”."},{type:"multiple_choice",question:"What does «ieri» mean?",options:["Monday","Tuesday","yesterday"],correct:2,explanation:"«ieri» means “yesterday”."},{type:"translate",question:"Write in Italian: “tomorrow”",correct:"domani",explanation:"“tomorrow” is «domani»."},{type:"translate",question:"Write in Italian: “Monday”",correct:"lunedì",explanation:"“Monday” is «lunedì»."}]}]}]},portuguese:{title:"Portuguese Passage",color:"#ef4444",sections:[{id:"portuguese-a1-1",title:"First words",tier:"A1",unlocked:!0,lessons:[{id:"portuguese-a1-greetings",title:"Greetings",icon:"👋",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Greetings",content:"Bom dia until lunch, boa tarde until dark, boa noite after. Thank you agrees with the speaker, not the listener: a man says obrigado, a woman says obrigada. The forms here are European Portuguese; Brazil shares almost all of them."},{type:"multiple_choice",question:"What does «olá» mean?",options:["hello","thank you (said by a man)","good morning"],correct:0,explanation:"«olá» means “hello”."},{type:"multiple_choice",question:"What does «boa noite» mean?",options:["please","good evening / good night","yes"],correct:1,explanation:"«boa noite» means “good evening / good night”."},{type:"multiple_choice",question:"What does «não» mean?",options:["hello","thank you (said by a man)","no"],correct:2,explanation:"«não» means “no”."},{type:"translate",question:"Write in Portuguese: “hello”",correct:"olá",explanation:"“hello” is «olá»."},{type:"translate",question:"Write in Portuguese: “goodbye”",correct:"adeus",explanation:"“goodbye” is «adeus»."}]},{id:"portuguese-a1-introductions",title:"Who I am",icon:"🧑",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Who I am",content:"To be for who you are: eu sou, tu és, ele é, ela é, nós somos. Portuguese has a second to be, estar, for passing states -- sou alto, I am tall, but estou cansado, I am tired. Tu is used in Portugal; Brazil mostly says você é."},{type:"multiple_choice",question:"What does «eu sou» mean?",options:["I am","you are","he is"],correct:0,explanation:"«eu sou» means “I am”."},{type:"multiple_choice",question:"What does «ela é» mean?",options:["we are","she is","my name is"],correct:1,explanation:"«ela é» means “she is”."},{type:"multiple_choice",question:"What does «prazer» mean?",options:["I am","you are","nice to meet you"],correct:2,explanation:"«prazer» means “nice to meet you”."},{type:"translate",question:"Write in Portuguese: “I am”",correct:"eu sou",explanation:"“I am” is «eu sou»."},{type:"translate",question:"Write in Portuguese: “we are”",correct:"nós somos",explanation:"“we are” is «nós somos»."}]},{id:"portuguese-a1-numbers",title:"Numbers 1-10",icon:"🔢",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers 1-10",content:"Um, dois, três. One and two agree with the noun: um livro but uma casa, dois gatos but duas casas. The tilde marks a nasal vowel, as in não."},{type:"multiple_choice",question:"What does «um» mean?",options:["one","two","three"],correct:0,explanation:"«um» means “one”."},{type:"multiple_choice",question:"What does «seis» mean?",options:["seven","six","eight"],correct:1,explanation:"«seis» means “six”."},{type:"multiple_choice",question:"What does «dez» mean?",options:["one","two","ten"],correct:2,explanation:"«dez» means “ten”."},{type:"translate",question:"Write in Portuguese: “two”",correct:"dois",explanation:"“two” is «dois»."},{type:"translate",question:"Write in Portuguese: “five”",correct:"cinco",explanation:"“five” is «cinco»."}]}]},{id:"portuguese-a1-2",title:"People and things",tier:"A1",unlocked:!0,lessons:[{id:"portuguese-a1-family",title:"Family",icon:"👪",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Family",content:"The words for the are o and a: o pai, a mãe. Os pais means the parents -- the masculine plural covers a mixed pair, so it is the plural of father that stands for both."},{type:"multiple_choice",question:"What does «a mãe» mean?",options:["the mother","the father","the brother"],correct:0,explanation:"«a mãe» means “the mother”."},{type:"multiple_choice",question:"What does «a irmã» mean?",options:["the son","the sister","the daughter"],correct:1,explanation:"«a irmã» means “the sister”."},{type:"multiple_choice",question:"What does «os pais» mean?",options:["the mother","the father","the parents"],correct:2,explanation:"«os pais» means “the parents”."},{type:"translate",question:"Write in Portuguese: “the father”",correct:"o pai",explanation:"“the father” is «o pai»."},{type:"translate",question:"Write in Portuguese: “the brother”",correct:"o irmão",explanation:"“the brother” is «o irmão»."}]},{id:"portuguese-a1-food",title:"Food and drink",icon:"🍞",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Food and drink",content:"Água is feminine: a água. Pão ends in a nasal sound, close to pown said through the nose. In a café, um café is an espresso, as in Italy."},{type:"multiple_choice",question:"What does «o pão» mean?",options:["the bread","the water","the milk"],correct:0,explanation:"«o pão» means “the bread”."},{type:"multiple_choice",question:"What does «o queijo» mean?",options:["the apple","the cheese","the coffee"],correct:1,explanation:"«o queijo» means “the cheese”."},{type:"multiple_choice",question:"What does «o chá» mean?",options:["the bread","the water","the tea"],correct:2,explanation:"«o chá» means “the tea”."},{type:"translate",question:"Write in Portuguese: “the milk”",correct:"o leite",explanation:"“the milk” is «o leite»."},{type:"translate",question:"Write in Portuguese: “the cheese”",correct:"o queijo",explanation:"“the cheese” is «o queijo»."}]},{id:"portuguese-a1-have",title:"I have",icon:"📚",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"I have",content:"To have: eu tenho, tu tens, ele tem, nós temos. Age uses to have, as in the other Romance languages: tenho vinte anos. Cão is the word in Portugal; Brazil says cachorro."},{type:"multiple_choice",question:"What does «eu tenho» mean?",options:["I have","you have","he has"],correct:0,explanation:"«eu tenho» means “I have”."},{type:"multiple_choice",question:"What does «um livro» mean?",options:["a house","a book","a cat"],correct:1,explanation:"«um livro» means “a book”."},{type:"multiple_choice",question:"What does «um cão» mean?",options:["I have","you have","a dog"],correct:2,explanation:"«um cão» means “a dog”."},{type:"translate",question:"Write in Portuguese: “I have”",correct:"eu tenho",explanation:"“I have” is «eu tenho»."},{type:"translate",question:"Write in Portuguese: “a cat”",correct:"um gato",explanation:"“a cat” is «um gato»."}]}]},{id:"portuguese-a1-3",title:"Getting around",tier:"A1",unlocked:!0,lessons:[{id:"portuguese-a1-questions",title:"Questions and directions",icon:"❓",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Questions and directions",content:"Onde, quando, como, quanto, quem. The word order of a question is the same as a statement; the rising voice does the work. À esquerda and à direita carry a grave accent because a plus a has merged into one."},{type:"multiple_choice",question:"What does «onde» mean?",options:["where","when","how"],correct:0,explanation:"«onde» means “where”."},{type:"multiple_choice",question:"What does «quanto» mean?",options:["who","how much","to the left"],correct:1,explanation:"«quanto» means “how much”."},{type:"multiple_choice",question:"What does «à direita» mean?",options:["where","when","to the right"],correct:2,explanation:"«à direita» means “to the right”."},{type:"translate",question:"Write in Portuguese: “where”",correct:"onde",explanation:"“where” is «onde»."},{type:"translate",question:"Write in Portuguese: “to the right”",correct:"à direita",explanation:"“to the right” is «à direita»."}]},{id:"portuguese-a1-days",title:"Days and time",icon:"📅",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Days and time",content:"Weekdays are numbered, not named after planets: segunda-feira is second day, because Sunday counts as the first. In speech the -feira is often dropped: até segunda, see you Monday."},{type:"multiple_choice",question:"What does «segunda-feira» mean?",options:["Monday","Tuesday","Wednesday"],correct:0,explanation:"«segunda-feira» means “Monday”."},{type:"multiple_choice",question:"What does «sábado» mean?",options:["Sunday","Saturday","today"],correct:1,explanation:"«sábado» means “Saturday”."},{type:"multiple_choice",question:"What does «ontem» mean?",options:["Monday","Tuesday","yesterday"],correct:2,explanation:"«ontem» means “yesterday”."},{type:"translate",question:"Write in Portuguese: “tomorrow”",correct:"amanhã",explanation:"“tomorrow” is «amanhã»."},{type:"translate",question:"Write in Portuguese: “Sunday”",correct:"domingo",explanation:"“Sunday” is «domingo»."}]}]}]},"math-counting":{title:"Counting",color:"#f43f5e",sections:[{id:"mc-sec",title:"Counting to a hundred",unlocked:!0,lessons:[{id:"mc-l1",title:"Counting to 20",icon:"1",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Numbers in order",content:"Numbers have a fixed order: 1, 2, 3, and so on. Counting up means moving forward in that order; counting down means moving back. Example: after 14 comes 15, and before 15 comes 14."},{type:"multiple_choice",question:"What comes after 14?",options:["13","15","16"],correct:1,explanation:"14 + 1 = 15."},{type:"multiple_choice",question:"What comes before 10?",options:["8","9","11"],correct:1,explanation:"9 + 1 = 10, so 9 comes right before 10."},{type:"translate",question:"Write the number that comes after 19.",correct:"20",explanation:"19 + 1 = 20."},{type:"multiple_choice",question:"Count backwards: 17, 16, 15, __?",options:["14","13","16"],correct:0,explanation:"Each step goes down by one: 15 - 1 = 14."},{type:"translate",question:"How many tens make 20?",correct:"2",explanation:"20 is 2 groups of ten."},{type:"multiple_choice",question:"Which number is missing? 5, 6, __, 8",options:["7","9","4"],correct:0,explanation:"The numbers go up by one each time, so 6 is followed by 7."}]},{id:"mc-l2",title:"Comparing numbers",icon:"<",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Bigger, smaller, or the same",content:"Two numbers can be compared: one can be bigger (>), smaller (<), or they can be equal (=). Example: 9 is bigger than 7, so we write 9 > 7."},{type:"multiple_choice",question:"Which sign goes between 8 and 5? 8 __ 5",options:["<",">","="],correct:1,explanation:"8 is bigger than 5, so the sign is >."},{type:"multiple_choice",question:"Which is bigger, 42 or 24?",options:["42","24","they are equal"],correct:0,explanation:"42 has more tens (4) than 24 (2 tens), so 42 is bigger."},{type:"multiple_choice",question:"13 __ 13",options:["<",">","="],correct:2,explanation:"The same number is neither bigger nor smaller than itself."},{type:"translate",question:"Write the bigger number: 56 or 65",correct:"65",explanation:"65 has 6 tens, 56 has 5 tens, so 65 is bigger."},{type:"multiple_choice",question:"Order from smallest: 30, 3, 13",options:["3, 13, 30","30, 13, 3","13, 3, 30"],correct:0,explanation:"3 is smallest, then 13, then 30."},{type:"multiple_choice",question:"Which is smaller, 19 or 91?",options:["19","91","equal"],correct:0,explanation:"19 has 1 ten, 91 has 9 tens, so 19 is smaller."}]},{id:"mc-l3",title:"Adding within 20",icon:"+",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Putting numbers together",content:"Adding means putting two amounts together to make one total. Example: 6 + 7 = 13, because starting at 6 and counting on 7 more lands on 13."},{type:"translate",question:"6 + 7 = ?",correct:"13",explanation:"6 + 7 = 13."},{type:"multiple_choice",question:"8 + 5 = ?",options:["12","13","14"],correct:1,explanation:"8 + 5 = 13."},{type:"translate",question:"9 + 9 = ?",correct:"18",explanation:"9 + 9 = 18."},{type:"multiple_choice",question:"There are 7 red apples and 6 green apples. How many apples in total?",options:["13","12","14"],correct:0,explanation:"7 + 6 = 13."},{type:"translate",question:"10 + 8 = ?",correct:"18",explanation:"10 + 8 = 18."},{type:"multiple_choice",question:"4 + 4 + 4 = ?",options:["8","12","16"],correct:1,explanation:"4 + 4 = 8, 8 + 4 = 12."}]},{id:"mc-l4",title:"Taking away within 20",icon:"-",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Taking some away",content:"Subtracting means taking an amount away from a total. Example: 15 - 6 = 9, because 6 taken away from 15 leaves 9."},{type:"translate",question:"15 - 6 = ?",correct:"9",explanation:"15 - 6 = 9."},{type:"multiple_choice",question:"18 - 9 = ?",options:["8","9","10"],correct:1,explanation:"18 - 9 = 9."},{type:"translate",question:"20 - 12 = ?",correct:"8",explanation:"20 - 12 = 8."},{type:"multiple_choice",question:"There were 16 birds; 7 flew away. How many are left?",options:["9","8","10"],correct:0,explanation:"16 - 7 = 9."},{type:"translate",question:"14 - 7 = ?",correct:"7",explanation:"14 - 7 = 7."},{type:"multiple_choice",question:"17 - 8 = ?",options:["9","8","10"],correct:0,explanation:"17 - 8 = 9."}]},{id:"mc-l5",title:"Tens and ones",icon:"10",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Every number is made of tens and ones",content:"A two-digit number is made of tens and ones. Example: 43 is 4 tens and 3 ones, because 4 tens is 40, plus 3 ones is 43."},{type:"multiple_choice",question:"How many tens in 67?",options:["6","7","67"],correct:0,explanation:"67 = 6 tens and 7 ones."},{type:"multiple_choice",question:"How many ones in 67?",options:["6","7","0"],correct:1,explanation:"67 = 6 tens and 7 ones."},{type:"translate",question:"4 tens and 5 ones make what number?",correct:"45",explanation:"4 tens is 40, plus 5 ones is 45."},{type:"multiple_choice",question:"Which number has 8 tens and 2 ones?",options:["28","82","80"],correct:1,explanation:"8 tens is 80, plus 2 ones is 82."},{type:"translate",question:"How many tens in 90?",correct:"9",explanation:"90 = 9 tens and 0 ones."},{type:"multiple_choice",question:"3 tens and 0 ones is",options:["3","30","300"],correct:1,explanation:"3 tens is 30."}]},{id:"mc-l6",title:"Adding within 100",icon:"+",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Adding two-digit numbers",content:"To add two two-digit numbers, add the ones, then the tens. Example: 34 + 25 -- ones: 4 + 5 = 9, tens: 30 + 20 = 50, total: 59."},{type:"translate",question:"34 + 25 = ?",correct:"59",explanation:"34 + 25 = 59."},{type:"multiple_choice",question:"42 + 31 = ?",options:["73","72","74"],correct:0,explanation:"42 + 31 = 73."},{type:"translate",question:"18 + 26 = ?",correct:"44",explanation:"18 + 26 = 44."},{type:"multiple_choice",question:"A shop sold 27 apples in the morning and 35 in the afternoon. How many in total?",options:["62","61","63"],correct:0,explanation:"27 + 35 = 62."},{type:"translate",question:"48 + 19 = ?",correct:"67",explanation:"48 + 19 = 67."},{type:"multiple_choice",question:"56 + 27 = ?",options:["83","82","84"],correct:0,explanation:"56 + 27 = 83."}]},{id:"mc-l7",title:"Taking away within 100",icon:"-",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Subtracting two-digit numbers",content:"To subtract two-digit numbers, sometimes a ten must be borrowed. Example: 52 - 27 -- 2 ones cannot take away 7, so borrow a ten: 12 - 7 = 5, and 4 tens - 2 tens = 2 tens, giving 25."},{type:"translate",question:"52 - 27 = ?",correct:"25",explanation:"52 - 27 = 25."},{type:"multiple_choice",question:"80 - 34 = ?",options:["46","44","56"],correct:0,explanation:"80 - 34 = 46."},{type:"translate",question:"63 - 19 = ?",correct:"44",explanation:"63 - 19 = 44."},{type:"multiple_choice",question:"There were 90 sweets; 58 were eaten. How many are left?",options:["32","42","22"],correct:0,explanation:"90 - 58 = 32."},{type:"translate",question:"100 - 45 = ?",correct:"55",explanation:"100 - 45 = 55."},{type:"multiple_choice",question:"71 - 38 = ?",options:["33","23","43"],correct:0,explanation:"71 - 38 = 33."}]},{id:"mc-l8",title:"Word problems within a hundred",icon:"?",xp:30,unlocked:!0,type:"lesson",work:"control",exercises:[{type:"lecture",question:"Reading before calculating",content:"A word problem gives numbers inside a story. First decide whether things are joined (add) or removed (subtract), then do the sum. Example: 23 stickers, 15 more bought -- joined, so add: 23 + 15 = 38."},{type:"multiple_choice",question:"Maria has 23 stickers. She buys 15 more. How many now?",options:["38","37","39"],correct:0,explanation:"23 + 15 = 38."},{type:"translate",question:"A box has 40 pencils. 16 are given away. How many are left?",correct:"24",explanation:"40 - 16 = 24."},{type:"multiple_choice",question:"There are 12 boys and 17 girls in a class. How many pupils?",options:["29","28","30"],correct:0,explanation:"12 + 17 = 29."},{type:"translate",question:"A farmer had 65 hens. He sold 28. How many are left?",correct:"37",explanation:"65 - 28 = 37."},{type:"multiple_choice",question:"Tom read 14 pages on Monday and 19 on Tuesday. How many pages in total?",options:["33","32","34"],correct:0,explanation:"14 + 19 = 33."},{type:"translate",question:"There were 50 cars in the car park. 23 left. How many remain?",correct:"27",explanation:"50 - 23 = 27."}]}]}]},"math-operations":{title:"Four operations",color:"#fb923c",sections:[{id:"mo-sec",title:"Multiply, divide, and solve",unlocked:!0,lessons:[{id:"mo-l1",title:"Multiplication as repeated addition",icon:"x",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Adding the same number many times",content:"Multiplication is repeated addition of the same number. Example: 4 x 3 means 4 added 3 times: 4 + 4 + 4 = 12."},{type:"translate",question:"4 x 3 = ?",correct:"12",explanation:"4 + 4 + 4 = 12."},{type:"multiple_choice",question:"5 x 2 = ?",options:["7","10","12"],correct:1,explanation:"5 + 5 = 10."},{type:"translate",question:"6 x 6 = ?",correct:"36",explanation:"6 x 6 = 36."},{type:"multiple_choice",question:"7 x 3 = ?",options:["21","20","24"],correct:0,explanation:"7 + 7 + 7 = 21."},{type:"translate",question:"8 x 4 = ?",correct:"32",explanation:"8 x 4 = 32."},{type:"multiple_choice",question:"There are 5 bags with 6 apples each. How many apples in total?",options:["30","25","35"],correct:0,explanation:"5 x 6 = 30."}]},{id:"mo-l2",title:"Multiplication tables",icon:"x",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Knowing the facts by heart",content:"Knowing multiplication facts up to 10 x 10 saves working them out every time. Example: 7 x 8 = 56 -- once known, it is instant."},{type:"translate",question:"7 x 8 = ?",correct:"56",explanation:"7 x 8 = 56."},{type:"multiple_choice",question:"9 x 6 = ?",options:["54","56","52"],correct:0,explanation:"9 x 6 = 54."},{type:"translate",question:"12 x 5 = ?",correct:"60",explanation:"12 x 5 = 60."},{type:"multiple_choice",question:"6 x 9 = ?",options:["54","48","56"],correct:0,explanation:"6 x 9 = 54, the same as 9 x 6."},{type:"translate",question:"7 x 7 = ?",correct:"49",explanation:"7 x 7 = 49."},{type:"multiple_choice",question:"8 x 8 = ?",options:["64","72","56"],correct:0,explanation:"8 x 8 = 64."}]},{id:"mo-l3",title:"Division as sharing",icon:"/",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Splitting into equal groups",content:"Division splits a total into equal groups. It is the inverse of multiplication: 12 / 3 = 4 because 4 x 3 = 12."},{type:"translate",question:"12 / 3 = ?",correct:"4",explanation:"12 / 3 = 4, since 4 x 3 = 12."},{type:"multiple_choice",question:"20 / 4 = ?",options:["5","4","6"],correct:0,explanation:"20 / 4 = 5, since 5 x 4 = 20."},{type:"translate",question:"45 / 9 = ?",correct:"5",explanation:"45 / 9 = 5, since 5 x 9 = 45."},{type:"multiple_choice",question:"24 sweets shared equally among 6 children. How many each?",options:["4","3","5"],correct:0,explanation:"24 / 6 = 4."},{type:"translate",question:"36 / 6 = ?",correct:"6",explanation:"36 / 6 = 6."},{type:"multiple_choice",question:"Which is the inverse fact of 7 x 8 = 56?",options:["56 / 8 = 6","56 / 8 = 7","8 / 7 = 56"],correct:1,explanation:"56 / 8 = 7, undoing the multiplication."}]},{id:"mo-l4",title:"Division with remainder",icon:"/",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"When it does not divide evenly",content:"Not every division comes out even. What is left over is the remainder. Example: 17 / 5 -- 5 x 3 = 15, and 17 - 15 = 2 left over, so 17 / 5 is 3 remainder 2."},{type:"multiple_choice",question:"17 / 5 = ? remainder ?",options:["3 remainder 2","3 remainder 1","4 remainder 0"],correct:0,explanation:"5 x 3 = 15, and 17 - 15 = 2."},{type:"translate",question:"How many times does 4 fit into 22, ignoring what is left over?",correct:"5",explanation:"4 x 5 = 20, which fits into 22 with 2 left over."},{type:"multiple_choice",question:"23 / 6 = ? remainder ?",options:["3 remainder 5","4 remainder 1","3 remainder 4"],correct:0,explanation:"6 x 3 = 18, and 23 - 18 = 5."},{type:"translate",question:"25 sweets shared among 4 children equally, how many are left over?",correct:"1",explanation:"4 x 6 = 24, and 25 - 24 = 1."},{type:"multiple_choice",question:"31 / 7 = ? remainder ?",options:["4 remainder 3","4 remainder 2","5 remainder 0"],correct:0,explanation:"7 x 4 = 28, and 31 - 28 = 3."},{type:"translate",question:"How many full weeks are in 17 days?",correct:"2",explanation:"7 x 2 = 14 fits into 17, with 3 days left over."}]},{id:"mo-l5",title:"Order of operations",icon:"()",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"What runs first",content:"Multiplication and division are done before addition and subtraction, unless brackets say otherwise. Example: 2 + 3 x 4 -- the multiplication runs first: 3 x 4 = 12, then 2 + 12 = 14."},{type:"translate",question:"2 + 3 x 4 = ?",correct:"14",explanation:"3 x 4 = 12 first, then 2 + 12 = 14."},{type:"multiple_choice",question:"10 - 2 x 3 = ?",options:["4","24","8"],correct:0,explanation:"2 x 3 = 6 first, then 10 - 6 = 4."},{type:"translate",question:"20 / 4 + 3 = ?",correct:"8",explanation:"20 / 4 = 5 first, then 5 + 3 = 8."},{type:"multiple_choice",question:"(2 + 3) x 4 = ?",options:["20","14","9"],correct:0,explanation:"Brackets run first: 2 + 3 = 5, then 5 x 4 = 20."},{type:"translate",question:"6 x 2 - 5 = ?",correct:"7",explanation:"6 x 2 = 12 first, then 12 - 5 = 7."},{type:"multiple_choice",question:"15 - 6 / 2 = ?",options:["12","4.5","6"],correct:0,explanation:"6 / 2 = 3 first, then 15 - 3 = 12."}]},{id:"mo-l6",title:"Multi-step word problems",icon:"?",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Breaking a problem into steps",content:"A harder word problem needs more than one step. Work out what the first step gives you, then use that result for the next step. Example: 5 rows of 9 chairs, 7 broken -- first 5 x 9 = 45, then 45 - 7 = 38."},{type:"multiple_choice",question:"A box holds 6 eggs. How many eggs in 8 boxes?",options:["48","42","54"],correct:0,explanation:"6 x 8 = 48."},{type:"translate",question:"There are 5 rows of chairs with 9 chairs in each row. 7 chairs are broken. How many working chairs?",correct:"38",explanation:"5 x 9 = 45, then 45 - 7 = 38."},{type:"multiple_choice",question:"A baker makes 60 buns and puts them equally into 5 boxes. How many buns per box?",options:["12","10","15"],correct:0,explanation:"60 / 5 = 12."},{type:"translate",question:"3 packs of pencils with 8 pencils each are shared equally between 4 children. How many pencils per child?",correct:"6",explanation:"3 x 8 = 24, then 24 / 4 = 6."},{type:"multiple_choice",question:"A class of 24 pupils is split into teams of 4. How many teams?",options:["6","5","8"],correct:0,explanation:"24 / 4 = 6."},{type:"translate",question:"A farmer has 7 baskets with 9 eggs each. He sells 40 eggs. How many eggs are left?",correct:"23",explanation:"7 x 9 = 63, then 63 - 40 = 23."}]},{id:"mo-l7",title:"Multiplying two-digit numbers",icon:"x",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Multiplying by a one-digit number",content:"A two-digit number can be split into tens and ones, each multiplied separately, then added. Example: 23 x 4 -- 20 x 4 = 80, and 3 x 4 = 12, so 80 + 12 = 92."},{type:"translate",question:"23 x 4 = ?",correct:"92",explanation:"20 x 4 = 80, 3 x 4 = 12, 80 + 12 = 92."},{type:"multiple_choice",question:"16 x 5 = ?",options:["80","75","85"],correct:0,explanation:"10 x 5 = 50, 6 x 5 = 30, 50 + 30 = 80."},{type:"translate",question:"32 x 3 = ?",correct:"96",explanation:"30 x 3 = 90, 2 x 3 = 6, 90 + 6 = 96."},{type:"multiple_choice",question:"14 x 6 = ?",options:["84","74","94"],correct:0,explanation:"10 x 6 = 60, 4 x 6 = 24, 60 + 24 = 84."},{type:"translate",question:"25 x 4 = ?",correct:"100",explanation:"20 x 4 = 80, 5 x 4 = 20, 80 + 20 = 100."},{type:"multiple_choice",question:"18 x 5 = ?",options:["90","85","95"],correct:0,explanation:"10 x 5 = 50, 8 x 5 = 40, 50 + 40 = 90."}]},{id:"mo-l8",title:"Dividing larger numbers",icon:"/",xp:35,unlocked:!0,type:"lesson",work:"control",exercises:[{type:"lecture",question:"Dividing a bigger number",content:"A larger division can be checked by asking what times the divisor gives the total. Example: 96 / 4 -- 4 x 24 = 96, so 96 / 4 = 24."},{type:"translate",question:"96 / 4 = ?",correct:"24",explanation:"4 x 24 = 96."},{type:"multiple_choice",question:"84 / 6 = ?",options:["14","12","16"],correct:0,explanation:"6 x 14 = 84."},{type:"translate",question:"72 / 8 = ?",correct:"9",explanation:"8 x 9 = 72."},{type:"multiple_choice",question:"108 / 9 = ?",options:["12","11","13"],correct:0,explanation:"9 x 12 = 108."},{type:"translate",question:"144 / 12 = ?",correct:"12",explanation:"12 x 12 = 144."},{type:"multiple_choice",question:"63 / 7 = ?",options:["9","8","10"],correct:0,explanation:"7 x 9 = 63."}]}]}]},"math-fractions":{title:"Fractions and parts",color:"#8b5cf6",sections:[{id:"mf-sec",title:"Fractions, per cent, and ratio",unlocked:!0,lessons:[{id:"mf-l1",title:"What a fraction is",icon:"1/2",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Parts of a whole",content:"A fraction shows equal parts of a whole. In 3/4, the bottom number (denominator) says how many equal parts the whole is cut into, and the top number (numerator) says how many of them are taken."},{type:"multiple_choice",question:"A pizza is cut into 8 equal slices; you eat 3. What fraction did you eat?",options:["3/8","8/3","3/5"],correct:0,explanation:"3 slices out of 8 equal slices is 3/8."},{type:"multiple_choice",question:"Which fraction is shaded if 2 out of 5 equal parts are coloured?",options:["2/5","5/2","2/3"],correct:0,explanation:"2 parts out of 5 is 2/5."},{type:"translate",question:"Write as a fraction: 1 part out of 4",correct:"1/4",explanation:"1 out of 4 equal parts is 1/4."},{type:"multiple_choice",question:"In the fraction 5/9, what is the denominator?",options:["5","9","4"],correct:1,explanation:"The denominator is the bottom number: 9."},{type:"translate",question:"In the fraction 3/7, what is the numerator?",correct:"3",explanation:"The numerator is the top number: 3."},{type:"multiple_choice",question:"Which fraction is bigger than a whole (improper)?",options:["3/4","4/3","2/5"],correct:1,explanation:"4/3 has more parts (4) than make a whole (3), so it is bigger than 1."}]},{id:"mf-l2",title:"Equivalent fractions",icon:"=",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"The same amount, different parts",content:"Multiplying (or dividing) both the numerator and the denominator by the same number gives an equivalent fraction, worth the same amount. Example: 1/2 = 2/4, because both parts were multiplied by 2."},{type:"multiple_choice",question:"Which fraction equals 1/2?",options:["2/4","2/5","3/5"],correct:0,explanation:"1/2 = 2/4, since both parts are multiplied by 2."},{type:"translate",question:"3/4 = ? / 8 (find the missing numerator)",correct:"6",explanation:"4 x 2 = 8, so the numerator is also x2: 3 x 2 = 6."},{type:"multiple_choice",question:"Which fraction equals 2/3?",options:["4/6","4/5","3/4"],correct:0,explanation:"2/3 = 4/6, since both parts are multiplied by 2."},{type:"translate",question:"1/5 = 2 / ? (find the missing denominator)",correct:"10",explanation:"1 x 2 = 2, so the denominator is also x2: 5 x 2 = 10."},{type:"multiple_choice",question:"Simplify 4/8 to lowest terms",options:["1/2","2/4","1/4"],correct:0,explanation:"4/8 divided by 4 on both parts is 1/2."},{type:"translate",question:"Simplify 6/9 to lowest terms",correct:"2/3",explanation:"6/9 divided by 3 on both parts is 2/3."}]},{id:"mf-l3",title:"Comparing fractions",icon:"<",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Which fraction is bigger",content:"With the same denominator, the bigger numerator wins. With different denominators, convert to a common one first, or think in terms of size: 3/4 is more than half, 1/3 is less than half."},{type:"multiple_choice",question:"Which is bigger, 3/8 or 5/8?",options:["3/8","5/8","equal"],correct:1,explanation:"Same denominator, so compare numerators: 5 > 3."},{type:"multiple_choice",question:"Which is bigger, 1/2 or 1/3?",options:["1/2","1/3","equal"],correct:0,explanation:"Cutting into fewer parts (2) makes each part bigger than cutting into more parts (3)."},{type:"multiple_choice",question:"Which is bigger, 2/3 or 3/4?",options:["2/3","3/4","equal"],correct:1,explanation:"2/3 is about 0.67 and 3/4 is 0.75, so 3/4 is bigger."},{type:"multiple_choice",question:"Which is smaller, 5/6 or 7/12?",options:["5/6","7/12","equal"],correct:1,explanation:"5/6 is about 0.83 and 7/12 is about 0.58, so 7/12 is smaller."},{type:"multiple_choice",question:"Order from smallest: 1/4, 1/2, 1/8",options:["1/8, 1/4, 1/2","1/2, 1/4, 1/8","1/4, 1/8, 1/2"],correct:0,explanation:"More parts means smaller pieces: 1/8 is smallest, 1/2 is largest."},{type:"multiple_choice",question:"Which is bigger, 3/5 or 2/5?",options:["3/5","2/5","equal"],correct:0,explanation:"Same denominator, so compare numerators: 3 > 2."}]},{id:"mf-l4",title:"Adding and subtracting fractions",icon:"+",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Same denominator, combine the tops",content:"When two fractions share the same denominator, add or subtract the numerators and keep the denominator. Example: 1/5 + 2/5 = 3/5."},{type:"translate",question:"1/5 + 2/5 = ?",correct:"3/5",explanation:"1 + 2 = 3, denominator stays 5."},{type:"multiple_choice",question:"3/7 + 2/7 = ?",options:["5/7","5/14","1/7"],correct:0,explanation:"3 + 2 = 5, denominator stays 7."},{type:"translate",question:"5/8 - 2/8 = ?",correct:"3/8",explanation:"5 - 2 = 3, denominator stays 8."},{type:"multiple_choice",question:"7/9 - 4/9 = ?",options:["3/9","4/9","1/9"],correct:0,explanation:"7 - 4 = 3, denominator stays 9."},{type:"translate",question:"2/6 + 3/6 = ?",correct:"5/6",explanation:"2 + 3 = 5, denominator stays 6."},{type:"multiple_choice",question:"1/4 + 1/4 = ?",options:["2/4","1/8","3/4"],correct:0,explanation:"1 + 1 = 2, denominator stays 4."}]},{id:"mf-l5",title:"Fractions, decimals and per cent",icon:"%",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Three ways to write the same amount",content:"A fraction, a decimal and a per cent can name the same amount. 1/2 = 0.5 = 50%. To get a percent from a fraction, divide the top by the bottom and multiply by 100."},{type:"multiple_choice",question:"1/4 as a decimal is",options:["0.25","0.4","0.14"],correct:0,explanation:"1 divided by 4 is 0.25."},{type:"multiple_choice",question:"1/2 as a per cent is",options:["50%","25%","12%"],correct:0,explanation:"1/2 = 0.5, and 0.5 x 100 = 50%."},{type:"translate",question:"3/4 as a per cent (number only, no % sign)",correct:"75",explanation:"3/4 = 0.75, and 0.75 x 100 = 75."},{type:"multiple_choice",question:"0.75 as a fraction is",options:["3/4","7/5","3/5"],correct:0,explanation:"0.75 = 75/100, which simplifies to 3/4."},{type:"translate",question:"1/5 as a decimal",correct:"0.2",explanation:"1 divided by 5 is 0.2."},{type:"multiple_choice",question:"20% as a fraction in lowest terms is",options:["1/5","1/4","2/10"],correct:0,explanation:"20/100 simplifies to 1/5."}]},{id:"mf-l6",title:"Per cent of a number",icon:"%",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Taking a percentage of an amount",content:"To find a per cent of a number, turn the per cent into a fraction (or decimal) and multiply. Example: 10% of 50 -- 10% is 10/100, so 10/100 x 50 = 5."},{type:"translate",question:"10% of 50 = ?",correct:"5",explanation:"10% of 50 = 5."},{type:"multiple_choice",question:"25% of 80 = ?",options:["20","25","16"],correct:0,explanation:"25% is a quarter: 80 / 4 = 20."},{type:"translate",question:"50% of 46 = ?",correct:"23",explanation:"50% is half: 46 / 2 = 23."},{type:"multiple_choice",question:"A 200 g bag is 20% sugar. How many grams of sugar?",options:["40","20","4"],correct:0,explanation:"20% of 200 = 40."},{type:"translate",question:"10% of 120 = ?",correct:"12",explanation:"10% of 120 = 12."},{type:"multiple_choice",question:"A shirt costs 40 and is reduced by 25%. How much is taken off the price?",options:["10","15","20"],correct:0,explanation:"25% of 40 = 10."}]},{id:"mf-l7",title:"Ratio basics",icon:":",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Comparing two amounts",content:"A ratio compares two amounts. 2:3 means for every 2 of the first there are 3 of the second. A ratio can be simplified the same way a fraction can, by dividing both sides by the same number."},{type:"multiple_choice",question:"A recipe uses flour and sugar in ratio 3:1. If there are 3 cups of flour, how much sugar?",options:["1 cup","3 cups","1/3 cup"],correct:0,explanation:"3:1 with 3 cups of flour means 1 cup of sugar."},{type:"translate",question:"Simplify the ratio 10:5 to lowest terms (write as a:b, e.g. 2:1)",correct:"2:1",explanation:"10:5 divided by 5 on both sides is 2:1."},{type:"multiple_choice",question:"A class has 12 boys and 8 girls. What is the ratio of boys to girls in lowest terms?",options:["3:2","2:3","4:3"],correct:0,explanation:"12:8 divided by 4 on both sides is 3:2."},{type:"translate",question:"Simplify the ratio 15:20 to lowest terms",correct:"3:4",explanation:"15:20 divided by 5 on both sides is 3:4."},{type:"multiple_choice",question:"A ratio of 1:4 means for every 1 part of the first there are how many parts of the second?",options:["4","1","5"],correct:0,explanation:"1:4 means 4 parts of the second for every 1 part of the first."},{type:"translate",question:"Share 30 sweets in the ratio 2:3. How many does the larger share get?",correct:"18",explanation:"2 + 3 = 5 parts, each part is 6, larger share is 3 x 6 = 18."}]},{id:"mf-l8",title:"Mixed word problems",icon:"?",xp:35,unlocked:!0,type:"lesson",work:"control",exercises:[{type:"lecture",question:"Fractions, per cent and ratio together",content:"Real problems mix fractions, per cent and ratio. The same idea underlies all three: a part compared to a whole. Read carefully to see which form the problem is using."},{type:"multiple_choice",question:"A tank is 3/4 full of 40 litres capacity. How many litres are in it?",options:["30","20","35"],correct:0,explanation:"3/4 of 40 = 30."},{type:"translate",question:"A shop had 60 shirts. 30% were sold. How many shirts are left?",correct:"42",explanation:"30% of 60 = 18 sold, 60 - 18 = 42 left."},{type:"multiple_choice",question:"Two bags of marbles are shared in the ratio 3:5. If there are 24 marbles in total, how many in the smaller bag?",options:["9","15","12"],correct:0,explanation:"3 + 5 = 8 parts, each part is 3, smaller bag is 3 x 3 = 9."},{type:"translate",question:"1/3 of a class of 27 pupils walk to school. How many pupils walk?",correct:"9",explanation:"1/3 of 27 = 9."},{type:"multiple_choice",question:"A price of 50 is increased by 10%. What is the new price?",options:["55","51","60"],correct:0,explanation:"10% of 50 = 5, and 50 + 5 = 55."},{type:"translate",question:"3/5 of 40 sweets are red. How many sweets are red?",correct:"24",explanation:"3/5 of 40 = 24."}]}]}]},"lang-reading-1":{title:"Reading a paragraph",color:"#34d399",sections:[{id:"lr1-sec",title:"Following a short text",unlocked:!0,lessons:[{id:"lr1-l1",title:"Who did what",icon:"📖",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A paragraph tells you who did what",content:"A short paragraph almost always has someone (or something) doing something. Before you answer any question, find the doer and the action first -- everything else hangs off those two."},{type:"lecture",question:"Read this",content:"Marek found a small blue bird on the path outside his house. The bird could not fly. Marek picked it up gently and put it in a box with soft cloth. He gave it water with a spoon. By the evening, the bird was hopping around the box."},{type:"multiple_choice",question:"Who found the bird?",options:["Marek","a neighbour","the bird’s mother"],correct:0},{type:"multiple_choice",question:"What was wrong with the bird?",options:["It was hungry","It could not fly","It was lost"],correct:1},{type:"multiple_choice",question:"What did Marek put in the box?",options:["Soft cloth","Leaves","A blanket and a toy"],correct:0},{type:"multiple_choice",question:"What happened by the evening?",options:["The bird flew away","The bird was hopping around","The bird fell asleep"],correct:1}]},{id:"lr1-l2",title:"Where and when",icon:"📍",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Where and when a thing happened",content:"A paragraph often says where something happened and when. These words are easy to skip past, but questions ask for them directly, so read for place and time on purpose."},{type:"lecture",question:"Read this",content:"On Saturday morning, Nina and her brother went to the market near the river. They bought apples, bread, and a bag of walnuts. On the way home it started to rain, so they waited under a bus shelter for ten minutes before walking on."},{type:"multiple_choice",question:"When did Nina and her brother go to the market?",options:["Saturday morning","Sunday evening","Friday afternoon"],correct:0},{type:"multiple_choice",question:"Where was the market?",options:["Near the river","Near the school","In the village square"],correct:0},{type:"multiple_choice",question:"What did they NOT buy?",options:["Apples","Walnuts","Cheese"],correct:2},{type:"multiple_choice",question:"Why did they wait under a bus shelter?",options:["They missed the bus","It started to rain","They were tired"],correct:1}]},{id:"lr1-l3",title:"Putting events in order",icon:"🔢",xp:20,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Events happen in an order",content:"A retelling has to keep the events in the order they happened, not the order you remember them. Look for words like first, then, after that, and finally -- they mark the sequence for you."},{type:"lecture",question:"Read this",content:"First, Oskar mixed flour, water, and salt into a soft dough. Then he rolled it flat with a wooden pin. After that, he cut the dough into small circles with a cup. Finally, he baked the circles in a hot oven until they turned golden brown."},{type:"word_arrange",question:"Put Oskar’s steps in the order they happened",words:["mixed flour, water and salt","rolled the dough flat","cut circles with a cup","baked the circles until golden"],correct:[0,1,2,3]},{type:"multiple_choice",question:"What did Oskar use to roll the dough?",options:["A cup","A wooden pin","His hands"],correct:1},{type:"multiple_choice",question:"What did Oskar use to cut the circles?",options:["A knife","A cup","Scissors"],correct:1}]},{id:"lr1-l4",title:"Retelling in your own words",icon:"🗣️",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Retelling means saying it shorter, not copying it",content:"A good retelling keeps the important facts and drops the small details. It is not the same sentences said back -- it is the story compressed into the parts that matter."},{type:"lecture",question:"Read this",content:"Ana’s class planted ten small trees behind the school on Tuesday. Each pupil dug a hole, placed a tree, and covered the roots with soil. The teacher watered every tree afterwards. Ana’s tree was the smallest one in the row."},{type:"multiple_choice",question:"Which sentence best retells the paragraph?",options:["Ana’s tree was the smallest in the row","On Tuesday, Ana’s class planted ten trees behind the school","The teacher watered the trees"],correct:1,explanation:"A retelling states the main event -- what happened, who, and roughly when -- rather than one small detail."},{type:"multiple_choice",question:"How many trees were planted?",options:["Ten","Twelve","One"],correct:0},{type:"multiple_choice",question:"Who watered the trees?",options:["Each pupil watered their own","The teacher","Nobody watered them"],correct:1},{type:"multiple_choice",question:"Whose tree was the smallest?",options:["The teacher’s","Ana’s","It does not say"],correct:1}]},{id:"lr1-l5",title:"A short story with two people",icon:"👥",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Keep track of who is who",content:"When a paragraph has two people, it is easy to mix up who did what. Reread carefully and match each action to its name before answering."},{type:"lecture",question:"Read this",content:"Petro and Lila found an old wooden box in the attic. Petro wanted to open it right away, but Lila said they should ask their grandmother first. Grandmother told them the box had belonged to her own mother and helped them open it together. Inside were old letters and a silver spoon."},{type:"multiple_choice",question:"Who wanted to open the box right away?",options:["Petro","Lila","Grandmother"],correct:0},{type:"multiple_choice",question:"Who suggested asking grandmother first?",options:["Petro","Lila","Neither"],correct:1},{type:"multiple_choice",question:"Whose box was it originally?",options:["Grandmother’s mother","Grandmother herself","Petro’s father"],correct:0},{type:"multiple_choice",question:"What was inside the box?",options:["Old letters and a silver spoon","Photographs and coins","A map and a key"],correct:0}]},{id:"lr1-l6",title:"Course control: reading a paragraph",icon:"🏆",xp:35,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Read this",content:"Every Friday, Denys helped his uncle at the small bakery near the station. He arrived at six in the morning, before the shop opened, and swept the floor while his uncle lit the oven. Once the bread went in, Denys arranged the fresh pastries in the window. Customers usually started arriving by seven thirty."},{type:"multiple_choice",question:"Which day did Denys help at the bakery?",options:["Friday","Sunday","Every day"],correct:0},{type:"multiple_choice",question:"What did Denys do while his uncle lit the oven?",options:["Swept the floor","Arranged pastries","Served customers"],correct:0},{type:"multiple_choice",question:"What did Denys do after the bread went in the oven?",options:["Went home","Arranged the fresh pastries in the window","Lit the oven himself"],correct:1},{type:"multiple_choice",question:"When did customers usually start arriving?",options:["Six in the morning","Seven thirty","Noon"],correct:1},{type:"lecture",question:"Read this",content:"Sofia’s cat, Musya, disappeared for two whole days. Sofia looked in the garden, under the porch, and behind the shed, but found nothing. On the third morning, she heard scratching in the garage and found Musya asleep on a pile of old blankets, safe and unhurt."},{type:"multiple_choice",question:"How long was Musya missing?",options:["One day","Two days","A week"],correct:1},{type:"multiple_choice",question:"Where did Sofia finally find Musya?",options:["Under the porch","Behind the shed","In the garage"],correct:2},{type:"word_arrange",question:"Put Sofia’s search in order",words:["looked in the garden","looked under the porch","looked behind the shed","heard scratching in the garage"],correct:[0,1,2,3]}]}]}]},"lang-reading-2":{title:"Reading for meaning",color:"#22c55e",sections:[{id:"lr2-sec",title:"What a text implies",unlocked:!0,lessons:[{id:"lr2-l1",title:"What a character feels but does not say",icon:"🤔",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A feeling can be shown without being named",content:'Writers often show a feeling through actions rather than saying "she was angry" directly. Slamming a door, going quiet, or refusing food can all point to a feeling the text never states outright. Your job is to read the action and name the feeling behind it.'},{type:"lecture",question:"Read this",content:"Ivo stared at his exam paper for a long time without writing anything. He kept tapping his pen on the desk and glancing at the clock. When the teacher announced ten minutes left, his hand started shaking slightly as he began to write very fast."},{type:"multiple_choice",question:"What does Ivo’s behaviour most likely show?",options:["He is bored","He is anxious about running out of time","He is proud of his answers"],correct:1,explanation:'Tapping the pen, watching the clock, and a shaking hand after the time warning all point to anxiety, not boredom or pride -- the text never says the word "anxious", but the actions build the picture.'},{type:"multiple_choice",question:"Why does the text mention the clock?",options:["To describe the classroom","To show Ivo is aware of time running out","Because the clock is broken"],correct:1,explanation:"Glancing at the clock, paired with the announcement of ten minutes left, signals that time pressure is the source of his behaviour."}]},{id:"lr2-l2",title:"What the author means by a phrase",icon:"💬",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A phrase can mean more than its plain words",content:"Sometimes a sentence carries more than its literal words, especially when it describes a habit or a comparison. Ask what point the author is making by choosing that particular phrase, not just what the words describe on the surface."},{type:"lecture",question:"Read this",content:'Every winter, Grandpa Yuri put on the same worn coat, the one with a patch on the elbow, and said the new coats in the shop "were made for people who throw things away too easily." He had worn it for over twenty years.'},{type:"multiple_choice",question:"What does Grandpa Yuri’s comment about new coats suggest?",options:["He cannot afford a new coat","He values keeping and repairing things over replacing them","He dislikes the colour of new coats"],correct:1,explanation:'The comment links "new coats" with people who "throw things away too easily", implying he values durability and repair over easily discarding old things -- not a comment about money or colour.'},{type:"multiple_choice",question:"What does the patch on the elbow suggest about the coat?",options:["It was recently bought","It has been repaired and kept in use for a long time","It was never worn"],correct:1,explanation:"A patch shows the coat was damaged and mended rather than replaced, matching the twenty years mentioned and his attitude toward new coats."}]},{id:"lr2-l3",title:"Why a character acted that way",icon:"❓",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Actions have reasons the text may not spell out",content:"A character’s choice often has a reason that is never stated in so many words. You have to connect an earlier detail to a later action to work out why something happened."},{type:"lecture",question:"Read this",content:"Nadia had saved money from three months of babysitting to buy a bicycle. On the day she finally had enough, she saw a poster for the animal shelter asking for donations to save a dog from being put down. She handed the shelter worker her entire savings and walked home without the bicycle."},{type:"multiple_choice",question:"Why did Nadia give away her savings?",options:["She no longer wanted a bicycle","She decided saving the dog mattered more to her than the bicycle","The shelter forced her to donate"],correct:1,explanation:"Nothing suggests she stopped wanting a bicycle or was forced; the text implies she weighed the two and chose the dog, showing what she valued more in that moment."},{type:"multiple_choice",question:"What can you conclude about Nadia’s character from this?",options:["She is careless with money","She is capable of a large, sudden act of generosity","She dislikes bicycles"],correct:1,explanation:"Giving up three months of savings instantly for a stranger’s cause is a significant, generous act, not carelessness or dislike of bicycles."}]},{id:"lr2-l4",title:"What is left unsaid between two people",icon:"🗨️",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Dialogue can hide more than it shows",content:"What people say to each other is not always the whole story. Short answers, changed subjects, or long pauses in a conversation often signal something a character is avoiding."},{type:"lecture",question:"Read this",content:'"How was the interview?" Marta asked. "Fine," said her brother, looking at the floor. "Did they say when they would call?" "Not really," he said, and quickly asked her what was for dinner.'},{type:"multiple_choice",question:"What does the brother’s change of subject most likely suggest?",options:["He genuinely wants to know about dinner","The interview did not go well and he does not want to talk about it","He forgot the interview happened"],correct:1,explanation:"Short answers, looking at the floor, and quickly changing the subject are classic signs of avoidance -- he is likely uncomfortable about how the interview went, not simply hungry."},{type:"multiple_choice",question:'What does "looking at the floor" suggest here?',options:["He is searching for something he dropped","He is uncomfortable or avoiding eye contact","The floor is interesting"],correct:1,explanation:"Avoiding eye contact while answering briefly is a common sign of discomfort or wanting to avoid a topic."}]},{id:"lr2-l5",title:"Drawing a conclusion from several clues",icon:"🔎",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Several small clues can add up to one conclusion",content:"Sometimes no single sentence gives you the answer -- several details together point toward it. Collect the clues before deciding what they add up to."},{type:"lecture",question:"Read this",content:"The kitchen light was still on at midnight. Two cups of cold tea sat untouched on the table, next to a pile of books about the ocean. A map of the coastline, marked with circles in red pen, lay open beside a half-packed bag."},{type:"multiple_choice",question:"What can you conclude is happening?",options:["Someone is planning a trip related to the sea, and stayed up late doing it","Someone just finished cleaning the kitchen","A party recently ended in the kitchen"],correct:0,explanation:"The books about the ocean, the marked coastline map, and the half-packed bag together suggest trip planning; the late hour and cold, untouched tea suggest they lost track of time doing it -- no single detail alone proves this, but together they do."},{type:"multiple_choice",question:"What do the untouched cups of cold tea suggest?",options:["The tea was never made","The person was too absorbed in something to drink it","Nobody was home"],correct:1,explanation:"Tea that has gone cold while sitting untouched suggests the person was distracted or absorbed in another task, matching the planning materials around it."}]},{id:"lr2-l6",title:"Course control: reading for meaning",icon:"🏆",xp:40,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Read this",content:"Roman checked his phone for the fifth time in ten minutes, though no message had come. He had already re-read the note he wrote for his presentation three times, even though he knew it by heart. When his name was finally called, he took a breath that seemed to last far too long before standing up."},{type:"multiple_choice",question:"What do Roman’s repeated actions most likely show?",options:["He is nervous before his presentation","He has forgotten his notes","He is expecting an important phone call and nothing else"],correct:0,explanation:"Checking the phone repeatedly for no reason, re-reading a memorised note, and a long breath before standing are all classic signs of nervousness before the presentation, not primarily about a phone call."},{type:"multiple_choice",question:'Why does the text mention he "knew it by heart"?',options:["To show he is careless","To show that re-reading it was about nerves, not about needing the information","To show he wrote it badly"],correct:1,explanation:"If he already knew it by heart, re-reading it again was not for the information -- it points to nervous repetition rather than a real need to check the content."},{type:"lecture",question:"Read this",content:'Every year, Mrs. Albescu planted the same row of sunflowers along the fence, even after her husband, who had loved them most, passed away. Neighbours sometimes offered to help her plant something easier to manage, but she always said the sunflowers were "no trouble at all."'},{type:"multiple_choice",question:"What is the most likely reason Mrs. Albescu keeps planting sunflowers?",options:["She genuinely finds them the easiest flower to grow","They are a way of remembering her husband","She dislikes other kinds of flowers"],correct:1,explanation:'The detail that her husband loved them most, combined with her continuing the tradition after his death and insisting they are "no trouble," suggests an emotional reason -- keeping his memory -- rather than a purely practical one.'},{type:"multiple_choice",question:'What does "no trouble at all" most likely mean here?',options:["A literal statement about how easy sunflowers are to grow","A way of avoiding the real, emotional reason she plants them","A complaint about the neighbours"],correct:1,explanation:"Given the emotional context, her insistence on ease reads as a way to deflect from the harder truth that the flowers are a form of remembrance."}]}]}]},"lang-reading-3":{title:"Working with a text",color:"#16a34a",sections:[{id:"lr3-sec",title:"Claim, evidence, and the gap between them",unlocked:!0,lessons:[{id:"lr3-l1",title:"Finding the claim",icon:"📌",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A claim is what the text wants you to believe",content:"A claim is the point a text is arguing for -- not a fact it happens to mention, but the position it is trying to establish. It is often stated near the start or the end, though not always in the most obvious sentence."},{type:"lecture",question:"Read this",content:"The town council should replace the old wooden footbridge with a concrete one. Three times in the last five years the wooden bridge has been closed for repair, each time for over a month. A concrete bridge, once built, would need almost no maintenance for decades. Yes, it would cost more to build, but the town spends nearly as much on yearly repairs already."},{type:"multiple_choice",question:"What is the claim of this text?",options:["The wooden bridge has been closed three times","The town council should replace the wooden bridge with a concrete one","Concrete costs more than wood"],correct:1,explanation:"The other statements are facts offered in support; the claim is the position the text is arguing for -- that the bridge should be replaced."},{type:"multiple_choice",question:"Which sentence states the claim most directly?",options:["The first sentence","The sentence about yearly repairs","The sentence about concrete needing little maintenance"],correct:0,explanation:"The opening sentence states the recommendation directly; the rest of the paragraph supports it."}]},{id:"lr3-l2",title:"Finding the evidence",icon:"🔍",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Evidence is what is offered to support the claim",content:"Evidence can be a fact, a number, an example, or an observation used to back up a claim. A text can offer strong evidence, weak evidence, or a mix -- your job right now is just to find what is offered, before judging how good it is."},{type:"lecture",question:"Read this",content:"Reading before bed helps children sleep better. A study of one school found that pupils who read for twenty minutes before bed fell asleep faster than pupils who used a screen in that same time. Teachers at the school also reported these pupils seemed more alert in morning lessons."},{type:"multiple_choice",question:"What is the claim in this text?",options:["Reading before bed helps children sleep better","Screens make children tired","Teachers prefer pupils who read"],correct:0},{type:"multiple_choice",question:"Which of these is evidence offered for the claim?",options:["Pupils who read fell asleep faster than pupils who used a screen","Reading is more enjoyable than screens","All children should read before bed"],correct:0,explanation:"The comparison between reading and screen use, drawn from an actual observation at the school, is the evidence; the other two options are opinions, not the evidence given."},{type:"multiple_choice",question:'What kind of evidence is the "more alert in morning lessons" detail?',options:["A number","A teacher observation","A quote from a pupil"],correct:1,explanation:"It is described as something teachers reported noticing, which is an observation, not a measured number or a direct quote."}]},{id:"lr3-l3",title:"When the evidence is thin",icon:"⚖️",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A gap appears when evidence does not fully support the claim",content:"A claim can be bigger than the evidence behind it. If a text claims something is always true, or true for everyone, but the evidence only covers one small case, there is a gap between what is claimed and what is actually shown."},{type:"lecture",question:"Read this",content:"Everyone learns a language faster by living abroad than by studying at home. My cousin moved to Portugal for a year and came back speaking fluent Portuguese, while she had barely progressed after two years of lessons at home. Living abroad is clearly the better method for anyone trying to learn a language."},{type:"multiple_choice",question:"What is the claim?",options:["My cousin moved to Portugal","Everyone learns a language faster by living abroad than by studying at home","Language lessons at home are useless"],correct:1},{type:"multiple_choice",question:"What is the evidence offered?",options:["One cousin’s experience with Portuguese","A study comparing many learners","Statistics on language learning"],correct:0},{type:"multiple_choice",question:"What is the gap between the claim and the evidence?",options:["There is no gap; the evidence fully supports the claim","The claim is about everyone, but the evidence is one single person’s story","The evidence contradicts the claim"],correct:1,explanation:'A claim about "everyone" needs evidence covering many different people; one cousin’s experience cannot establish what is true for everyone, no matter how convincing that one story feels.'}]},{id:"lr3-l4",title:"Evidence that pulls the other way",icon:"🔄",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Sometimes a text includes evidence against its own claim",content:"A careful text sometimes mentions a fact that actually weakens its own claim, either without noticing or while trying to explain it away. Spotting this tension is a sharper skill than just finding supporting evidence."},{type:"lecture",question:"Read this",content:"The new cafeteria menu has been a success, with students reporting they enjoy the food far more than before. However, the amount of food thrown away each day has actually increased since the new menu started, and fewer students are finishing their trays than last year."},{type:"multiple_choice",question:"What is the claim?",options:["The new cafeteria menu has been a success","Students throw away more food than before","Fewer students are finishing their trays"],correct:0},{type:"multiple_choice",question:"Which detail sits in tension with the claim of success?",options:["Students reporting they enjoy the food more","More food being thrown away and fewer trays finished","The menu being new"],correct:1,explanation:"If the menu were a clear success, you would expect less waste and more finished trays, not more waste and fewer finished trays -- this detail pulls against the claim rather than supporting it."},{type:"multiple_choice",question:"What would resolve this tension, if it were added to the text?",options:["A reason for the extra waste that is unrelated to whether students like the food","Another sentence saying the menu is popular","Removing the claim entirely"],correct:0,explanation:"An explanation -- for example, portions being too large -- could show the waste is not really evidence against the claim; without such an explanation, the gap remains unresolved."}]},{id:"lr3-l5",title:"A claim built on a comparison",icon:"📈",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A comparison must compare fairly",content:"A text sometimes supports a claim by comparing two things, but the comparison can be unfair -- the two things might not be alike in the ways that matter. Check whether the comparison actually supports the claim or just looks like it does."},{type:"lecture",question:"Read this",content:"The company’s new factory is far safer than its old one: last year the new factory had only two reported injuries, compared to fifteen at the old factory the year before it closed. The new factory is clearly a safer place to work."},{type:"multiple_choice",question:"What is the claim?",options:["The new factory is clearly a safer place to work","The old factory had fifteen injuries","The new factory closed last year"],correct:0},{type:"multiple_choice",question:"What evidence is offered?",options:["A comparison of injury counts between the two factories","A safety inspector’s report","Worker interviews"],correct:0},{type:"multiple_choice",question:"What information is missing to judge the comparison fairly?",options:["The colour of the factories","Whether the new factory employs the same number of workers as the old one","The name of the factory manager"],correct:1,explanation:"If the new factory employs far fewer workers, fewer injuries would be expected regardless of safety -- without knowing the number of workers, the comparison of raw injury counts does not clearly support the claim."}]},{id:"lr3-l6",title:"Course control: working with a text",icon:"🏆",xp:45,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Read this",content:"Switching the school day to start an hour later would improve student performance. A nearby school that delayed its start time by fifty minutes reported that test scores in morning classes rose the following term. Attendance also improved slightly. However, the same school reported that after-school clubs saw lower attendance, since the school day now ended later."},{type:"multiple_choice",question:"What is the claim?",options:["Switching the school day to start later would improve student performance","Test scores always rise in the morning","After-school clubs are unimportant"],correct:0},{type:"multiple_choice",question:"Which detail is evidence supporting the claim?",options:["Test scores in morning classes rose the following term","The school day now ends later","After-school clubs saw lower attendance"],correct:0},{type:"multiple_choice",question:"Which detail creates a gap or tension with the claim?",options:["Attendance improved slightly","Lower attendance at after-school clubs","The nearby school delayed its start by fifty minutes"],correct:1,explanation:'A drop in after-school club attendance is a cost the text does not fully address when it claims the change simply "would improve student performance" -- it complicates a claim about overall improvement.'},{type:"lecture",question:"Read this",content:"This brand of running shoe is the best choice for new runners: in a review of ten shoes by one sports magazine, it was rated most comfortable by testers. It is also the most expensive of the ten shoes reviewed."},{type:"multiple_choice",question:"What is the claim?",options:["This brand of running shoe is the best choice for new runners","It was rated most comfortable","It is the most expensive shoe reviewed"],correct:0},{type:"multiple_choice",question:"What is the evidence given?",options:["It was rated most comfortable by testers in one review","It is popular among professional athletes","It is made from recycled materials"],correct:0},{type:"multiple_choice",question:"What gap exists between the claim and the evidence?",options:['Comfort in one review does not establish it is the "best choice for new runners", especially given the high price and no mention of cost being weighed',"There is no gap; comfort is the only thing that matters","The evidence contradicts the claim entirely"],correct:0,explanation:'Being rated comfortable does not by itself establish "best choice for new runners" -- price, durability, and suitability for beginners are not addressed, so the claim reaches further than the evidence given.'}]}]}]},"lang-reading-4":{title:"Writing an argument",color:"#059669",sections:[{id:"lr4-sec",title:"Building and answering a case",unlocked:!0,lessons:[{id:"lr4-l1",title:"Claim, reason, and rebuttal",icon:"🧩",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"The three parts of a written argument",content:"A claim states your position. A reason explains why the claim is true. A rebuttal answers the strongest objection someone could raise against your claim. A written argument usually needs all three, in that rough order, to feel complete rather than one-sided."},{type:"multiple_choice",question:"Prompt: schools should allow phones during breaks. Which sentence is the claim?",options:["Schools should allow students to use phones during breaks","Some students use phones to call their parents","Phones can be a distraction in class"],correct:0,explanation:"This sentence states the position being argued for. The others are supporting material or a point against it, not the claim itself."},{type:"multiple_choice",question:"Which sentence is a reason supporting that claim?",options:["Phones should be banned everywhere","Break time is meant for students to relax and manage their own time, and phones are part of that","Teachers dislike phones"],correct:1,explanation:"A reason explains why the claim should be accepted; this sentence gives a justification tied to the purpose of break time."},{type:"multiple_choice",question:"Which sentence is a rebuttal to an objection?",options:["Phones are useful","Some worry phones during breaks lead to phone use in class too, but a clear rule limiting phones to breaks only addresses that directly","Students like phones"],correct:1,explanation:"A rebuttal names the objection (phone use spreading into class) and answers it directly, rather than repeating the claim."}]},{id:"lr4-l2",title:"Recognising the strongest objection",icon:"🛡️",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A weak objection is easy to ignore; a strong one has to be answered",content:"Before you can write a rebuttal, you have to find the objection that actually threatens your claim, not a minor one that is easy to dismiss. A strong objection points at a real weak spot in your reasoning."},{type:"multiple_choice",question:"Claim: the town should build a new library because the old one is too small for its visitors. Which is the strongest objection?",options:["Some people prefer reading at home","The town has limited money, and a new library might mean cutting another needed service","Libraries are old-fashioned"],correct:1,explanation:'This objection engages directly with the practical cost of the claim -- a real constraint that must be addressed. The other two are weaker: personal preference does not challenge whether a bigger library is needed, and calling libraries "old-fashioned" is a vague opinion, not a specific threat to the claim.'},{type:"multiple_choice",question:"Claim: students should be given more time for a single final exam. Which is the strongest objection?",options:["Some students might use the extra time to check social media instead of working","More time for the exam could put pressure on the schedule for other classes and staff","Exams are stressful"],correct:1,explanation:'This directly challenges the practicality of the claim with a scheduling constraint that would have to be solved. Checking social media is a minor behavioural issue that does not undercut the core claim, and "exams are stressful" is unrelated to the specific claim about time.'}]},{id:"lr4-l3",title:"Producing a rebuttal, not a repeat",icon:"✍️",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A real rebuttal answers the objection, it does not restate the claim",content:"A common mistake is to respond to an objection by simply repeating the original claim louder. A real rebuttal acknowledges the objection has a point, then explains why the claim still holds despite it -- often by adding a condition, a limit, or a missing piece of context."},{type:"translate",question:"Claim: the school should serve only vegetarian food on Mondays. Objection: some students need more protein than vegetarian meals easily provide. Write a short rebuttal phrase that answers this specific objection (not a repeat of the claim).",correct:"vegetarian meals can include beans, eggs, or dairy for enough protein",acceptable:["beans and dairy provide enough protein","a vegetarian menu can still include high-protein foods like eggs and beans","protein needs can be met with beans, lentils, eggs, or dairy"],explanation:"A working rebuttal directly answers the protein concern by naming vegetarian protein sources, rather than repeating that vegetarian food is a good idea."},{type:"multiple_choice",question:'Which of these actually functions as a rebuttal to "the new road will increase traffic near the school"?',options:["The new road is definitely a good idea","The road can include a reduced speed limit and a crossing guard near the school to manage the extra traffic safely","Traffic is not a real problem"],correct:1,explanation:"This answer accepts the objection has a real basis (more traffic) and offers a specific way to address the safety concern, rather than denying the problem or simply restating support for the road."}]},{id:"lr4-l4",title:"Concession: agreeing without losing the claim",icon:"🤝",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A concession admits a point without giving up the argument",content:"A concession is when you openly agree that part of the objection is true, and then explain why your overall claim still stands. This is different from a rebuttal that denies the objection outright -- a concession makes an argument more honest and often more convincing, because it shows you considered the other side fairly."},{type:"multiple_choice",question:"Claim: the town should reduce the speed limit near the school. Which sentence is a concession (not a plain rebuttal or a repeat)?",options:["A lower speed limit will not stop every accident, but it gives drivers more time to react near where children cross","The speed limit must be reduced immediately","Nobody could object to a lower speed limit"],correct:0,explanation:'This sentence admits a limit ("will not stop every accident") before restating why the claim still holds -- that is a concession. The other options either simply repeat the claim or deny that any objection could exist.'},{type:"multiple_choice",question:"Which of these openings signals a concession is coming?",options:['"It is completely obvious that..."','"While it is true that..."','"Nobody would ever say that..."'],correct:1,explanation:'"While it is true that" is a standard way to admit a valid point before pivoting back to the main claim -- the classic shape of a concession.'}]},{id:"lr4-l5",title:"Building a short case, step by step",icon:"🧱",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Putting claim, reason, concession, and rebuttal in order",content:"A short written argument usually flows: claim, then reason, then a fair concession to the strongest objection, then a rebuttal that shows the claim still holds. Getting this order right makes the case easy for a reader to follow."},{type:"word_arrange",question:"Order these parts of a short argument about a class trip",words:["claim: the class should take a trip to the science museum","reason: it connects directly to the current unit on energy","concession: the trip does cost money and takes a full school day","rebuttal: the museum offers a discounted group rate and the day can replace a normal lesson, not add to the schedule"],correct:[0,1,2,3]},{type:"multiple_choice",question:"In a well-ordered argument, why does the reason come before the concession?",options:["Alphabetical order requires it","The case for the claim should be established before admitting a weakness against it","It does not matter what order they come in"],correct:1,explanation:"Stating the reason first gives the claim some support before the argument turns to acknowledge a weakness -- admitting the weakness first, with no case yet made, would leave the claim looking undefended."}]},{id:"lr4-l6",title:"Course control: writing an argument",icon:"🏆",xp:45,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Prompt: the school cafeteria should stop selling sugary drinks",content:"Read the claim above and answer the questions that follow about how to build and defend an argument around it."},{type:"multiple_choice",question:"Which sentence is a reason supporting this claim?",options:["Some students dislike water","Removing sugary drinks would reduce the amount of sugar students consume during the school day","Cafeterias are often crowded at lunch"],correct:1,explanation:"This sentence gives a justification directly tied to the claim -- less sugar consumed -- rather than an unrelated fact or a minor preference."},{type:"multiple_choice",question:'A student objects: "Some families rely on the cafeteria selling drinks cheaply, and removing sugary drinks removes their only affordable option." What kind of response would be a genuine rebuttal, not a repeat of the claim?',options:["Sugary drinks should still be banned regardless","The cafeteria could keep prices low by offering cheap water and milk instead, so an affordable option remains","That objection does not matter"],correct:1,explanation:"A real rebuttal answers the specific concern raised (affordability) with a concrete solution, rather than dismissing it or simply restating the original claim."},{type:"multiple_choice",question:"Which sentence below is a concession, admitting a fair point before returning to the claim?",options:["It is true that some students will be unhappy about losing their favourite drink, but the health benefit for the whole school outweighs that inconvenience","The claim is completely correct and nobody could disagree","Sugary drinks are always bad in every situation"],correct:0,explanation:"This sentence openly admits a real downside (student unhappiness) before pivoting back to defend the claim -- the shape of a concession, not a denial or a repeat."},{type:"multiple_choice",question:"Which structure best matches claim → reason → concession → rebuttal, in order?",options:["The cafeteria should stop selling sugary drinks. This reduces sugar intake school-wide. Some students will be upset. A cheaper alternative like milk keeps an affordable option available.","Sugary drinks are bad. Sugar is bad for teeth. Everyone agrees. The end.","Milk is healthy. Sugar is unhealthy. Some students like sugar. The cafeteria sells both."],correct:0,explanation:"The first option states the claim, gives a reason, admits a real cost (concession), and answers it directly (rebuttal) -- the complete shape covered in this course. The others skip or blur these parts."},{type:"translate",question:'Objection: "Banning sugary drinks will just push students to buy them from shops outside school instead." Write a short rebuttal phrase (not a repeat of the claim) that answers this specific concern.',correct:"the school can offer better and cheaper alternatives inside so students have less reason to buy outside",acceptable:["offering appealing alternatives inside reduces the reason to buy outside","making healthy drinks cheap and available inside addresses that concern","the school could pair the ban with cheap healthy options so fewer students go outside"],explanation:"A working rebuttal names the specific worry (students buying outside) and offers a concrete way to reduce that outcome, rather than simply restating that the ban is a good idea."}]}]}]},"math-algebra":{title:"Letters for numbers",color:"#e11d48",sections:[{id:"ma-sec",title:"Expressions and linear equations",unlocked:!0,lessons:[{id:"ma-l1",title:"Simplifying expressions",icon:"x",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Like terms can be combined",content:"A letter such as x stands for a number we do not yet know. Terms with the same letter (like terms) can be added or subtracted just like counting objects. Example: 3x + 5x means 3 copies of x plus 5 copies of x, giving 8 copies of x, so 3x + 5x = 8x."},{type:"translate",question:"Simplify: 3x + 5x",correct:"8x",explanation:"3 copies of x plus 5 copies of x is 8 copies of x: 3x + 5x = 8x."},{type:"multiple_choice",question:"Simplify: 7y - 2y",options:["5y","9y","14y"],correct:0,explanation:"7 copies of y minus 2 copies of y leaves 5 copies of y."},{type:"translate",question:"Simplify: 4a + 3a + a",correct:"8a",explanation:"4a + 3a + a = 4a + 3a + 1a = 8a."},{type:"multiple_choice",question:"Which of these is a like term to 5x?",options:["5y","2x","5"],correct:1,explanation:"A like term must have the same letter; 2x has the letter x, same as 5x."},{type:"translate",question:"Simplify: 9b - 4b + 2b",correct:"7b",explanation:"9b - 4b = 5b, then 5b + 2b = 7b."},{type:"multiple_choice",question:"Simplify: 2x + 3 + 5x",options:["7x + 3","10x","7x"],correct:0,explanation:"Only the x terms combine: 2x + 5x = 7x, the plain number 3 stays separate: 7x + 3."}]},{id:"ma-l2",title:"What an equation says",icon:"=",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Both sides balance",content:"An equation says two amounts are equal, like a balanced scale. Whatever is done to one side must be done to the other to keep it balanced. To find x in x + 3 = 10, subtract 3 from both sides: x + 3 - 3 = 10 - 3, so x = 7. Check: 7 + 3 = 10, correct."},{type:"translate",question:"Solve: x + 3 = 10",correct:"7",explanation:"Subtract 3 from both sides: x = 10 - 3 = 7. Check: 7 + 3 = 10."},{type:"multiple_choice",question:"Solve: x + 5 = 12",options:["6","7","17"],correct:1,explanation:"x = 12 - 5 = 7. Check: 7 + 5 = 12."},{type:"translate",question:"Solve: x - 4 = 9",correct:"13",explanation:"Add 4 to both sides: x = 9 + 4 = 13. Check: 13 - 4 = 9."},{type:"multiple_choice",question:"Solve: n + 5 = 12",options:["7","17","5"],correct:0,explanation:"n = 12 - 5 = 7. Check: 7 + 5 = 12."},{type:"translate",question:"Solve: 3n = 21",correct:"7",explanation:"Divide both sides by 3: n = 21 / 3 = 7. Check: 3 x 7 = 21."},{type:"multiple_choice",question:"What must be done to both sides of x - 8 = 15 to isolate x?",options:["Subtract 8","Add 8","Multiply by 8"],correct:1,explanation:"Adding 8 undoes the subtraction of 8, isolating x."}]},{id:"ma-l3",title:"One-step equations",icon:"x",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Undoing one operation",content:"A one-step equation needs a single undoing move: undo addition with subtraction, undo multiplication with division. Example: 5x = 30 -- divide both sides by 5: x = 30 / 5 = 6. Check: 5 x 6 = 30, correct."},{type:"translate",question:"Solve: 5x = 30",correct:"6",explanation:"Divide both sides by 5: x = 30 / 5 = 6. Check: 5 x 6 = 30."},{type:"multiple_choice",question:"Solve: 4x = 28",options:["6","7","8"],correct:1,explanation:"x = 28 / 4 = 7. Check: 4 x 7 = 28."},{type:"translate",question:"Solve: x / 3 = 9",correct:"27",explanation:"Multiply both sides by 3: x = 9 x 3 = 27. Check: 27 / 3 = 9."},{type:"multiple_choice",question:"Solve: x / 5 = 4",options:["9","20","1"],correct:1,explanation:"Multiply both sides by 5: x = 4 x 5 = 20. Check: 20 / 5 = 4."},{type:"translate",question:"Solve: 8x = 56",correct:"7",explanation:"x = 56 / 8 = 7. Check: 8 x 7 = 56."},{type:"multiple_choice",question:"Solve: x + 9 = 9",options:["0","9","18"],correct:0,explanation:"x = 9 - 9 = 0. Check: 0 + 9 = 9."}]},{id:"ma-l4",title:"Two-step equations",icon:"xx",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Undo addition first, then multiplication",content:"A two-step equation needs two undoing moves, in reverse order of how the equation was built: undo the added or subtracted number first, then undo the multiplication. Example: 2x - 4 = 8 -- add 4 to both sides: 2x = 12, then divide by 2: x = 6. Check: 2 x 6 - 4 = 12 - 4 = 8, correct."},{type:"translate",question:"Solve: 2x - 4 = 8",correct:"6",explanation:"Add 4: 2x = 12. Divide by 2: x = 6. Check: 2(6) - 4 = 8."},{type:"multiple_choice",question:"Solve: 3x + 5 = 20",options:["5","15","25"],correct:0,explanation:"Subtract 5: 3x = 15. Divide by 3: x = 5. Check: 3(5) + 5 = 20."},{type:"translate",question:"Solve: 5x - 7 = 18",correct:"5",explanation:"Add 7: 5x = 25. Divide by 5: x = 5. Check: 5(5) - 7 = 18."},{type:"multiple_choice",question:"Solve: 4x + 2 = 22",options:["5","6","20"],correct:0,explanation:"Subtract 2: 4x = 20. Divide by 4: x = 5. Check: 4(5) + 2 = 22."},{type:"translate",question:"Solve: 6x - 3 = 21",correct:"4",explanation:"Add 3: 6x = 24. Divide by 6: x = 4. Check: 6(4) - 3 = 21."},{type:"multiple_choice",question:"Solve: 2x + 9 = 17",options:["3","4","13"],correct:1,explanation:"Subtract 9: 2x = 8. Divide by 2: x = 4. Check: 2(4) + 9 = 17."}]},{id:"ma-l5",title:"Combining like terms in an equation",icon:"x+x",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Simplify first, then solve",content:"When the same letter appears more than once in an equation, combine those terms first, then solve as usual. Example: 4x + 2x = 18 -- combine to 6x = 18, then divide by 6: x = 3. Check: 4(3) + 2(3) = 12 + 6 = 18, correct."},{type:"translate",question:"Solve: 4x + 2x = 18",correct:"3",explanation:"Combine: 6x = 18. Divide: x = 3. Check: 4(3) + 2(3) = 18."},{type:"multiple_choice",question:"Solve: 7x - 2x = 25",options:["5","23","3.5"],correct:0,explanation:"Combine: 5x = 25. Divide: x = 5. Check: 7(5) - 2(5) = 35 - 10 = 25."},{type:"translate",question:"Solve: 3x + x = 16",correct:"4",explanation:"Combine: 4x = 16 (since x is 1x). Divide: x = 4. Check: 3(4) + 4 = 16."},{type:"multiple_choice",question:"Solve: 8x - 3x + 1 = 26",options:["5","25","3"],correct:0,explanation:"Combine: 5x + 1 = 26. Subtract 1: 5x = 25. Divide: x = 5. Check: 8(5) - 3(5) + 1 = 40 - 15 + 1 = 26."},{type:"translate",question:"Solve: 2x + 5x - 4 = 24",correct:"4",explanation:"Combine: 7x - 4 = 24. Add 4: 7x = 28. Divide: x = 4. Check: 2(4) + 5(4) - 4 = 8 + 20 - 4 = 24."},{type:"multiple_choice",question:"Solve: 6x - x = 20",options:["4","5","20"],correct:0,explanation:"Combine: 5x = 20 (since 6x - x = 5x). Divide: x = 4. Check: 5(4)=20, so x = 4.",hint:"Careful: 6x - x = 5x, not 6x."}]},{id:"ma-l6",title:"Word problems as equations",icon:"?",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Turning a story into an equation",content:'A word problem describes a relationship in words; naming the unknown x and writing that relationship as an equation lets the earlier steps solve it. Example: "A number, plus 6, is 20" becomes x + 6 = 20, so x = 14. Check: 14 + 6 = 20, correct.'},{type:"multiple_choice",question:"A number plus 6 is 20. Which equation says this?",options:["x + 6 = 20","6x = 20","x - 6 = 20"],correct:0,explanation:'"plus 6" means adding 6 to the unknown: x + 6 = 20.'},{type:"translate",question:"A number plus 6 is 20. What is the number?",correct:"14",explanation:"x + 6 = 20, so x = 20 - 6 = 14. Check: 14 + 6 = 20."},{type:"multiple_choice",question:"Three times a number is 27. Which equation says this?",options:["x + 3 = 27","3x = 27","x / 3 = 27"],correct:1,explanation:'"three times a number" means 3 multiplied by the unknown: 3x = 27.'},{type:"translate",question:"Three times a number is 27. What is the number?",correct:"9",explanation:"3x = 27, so x = 27 / 3 = 9. Check: 3(9) = 27."},{type:"translate",question:"A number, doubled, then increased by 5, is 21. What is the number?",correct:"8",explanation:"2x + 5 = 21. Subtract 5: 2x = 16. Divide: x = 8. Check: 2(8) + 5 = 21."},{type:"multiple_choice",question:"A ticket costs x dollars. Buying 4 tickets costs 52 dollars. What is x?",options:["12","13","48"],correct:1,explanation:"4x = 52, so x = 52 / 4 = 13. Check: 4(13) = 52."}]},{id:"ma-l7",title:"Course control: solving linear equations",icon:"🏆",xp:45,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Show what was learned",content:"This control test checks simplifying expressions and solving one-step, two-step, and word-problem equations, the way this course covered them."},{type:"multiple_choice",question:"Simplify: 5x + 3x",options:["8x","15x","8"],correct:0,explanation:"5x + 3x = 8x."},{type:"translate",question:"Solve: x + 9 = 15",correct:"6",explanation:"x = 15 - 9 = 6. Check: 6 + 9 = 15."},{type:"multiple_choice",question:"Solve: 6x = 42",options:["6","7","8"],correct:1,explanation:"x = 42 / 6 = 7. Check: 6(7) = 42."},{type:"translate",question:"Solve: 3x - 5 = 16",correct:"7",explanation:"Add 5: 3x = 21. Divide by 3: x = 7. Check: 3(7) - 5 = 16."},{type:"multiple_choice",question:"A number times 4, minus 6, is 26. What is the number?",options:["8","9","20"],correct:0,explanation:"4x - 6 = 26. Add 6: 4x = 32. Divide: x = 8. Check: 4(8) - 6 = 26."}]}]}]},"math-functions":{title:"Functions and graphs",color:"#0891b2",sections:[{id:"mfn-sec",title:"Rules, graphs, and slope",unlocked:!0,lessons:[{id:"mfn-l1",title:"What a function is",icon:"f(x)",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"One input, one output",content:"A function is a rule that takes an input and gives exactly one output for it. Writing y = x + 2 means: whatever x is put in, add 2 to get y. Example: if x = 3, then y = 3 + 2 = 5."},{type:"translate",question:"If y = x + 2 and x = 3, what is y?",correct:"5",explanation:"y = 3 + 2 = 5."},{type:"multiple_choice",question:"If y = x + 2 and x = 7, what is y?",options:["8","9","5"],correct:1,explanation:"y = 7 + 2 = 9."},{type:"translate",question:"If y = 2x and x = 6, what is y?",correct:"12",explanation:"y = 2 x 6 = 12."},{type:"multiple_choice",question:"A function takes an input of 5 and always gives the same output. What is this called?",options:["a coincidence","a function","an equation only"],correct:1,explanation:"A rule that gives exactly one output per input is a function -- that is the definition used here."},{type:"translate",question:"If y = x - 4 and x = 10, what is y?",correct:"6",explanation:"y = 10 - 4 = 6."},{type:"multiple_choice",question:"If y = 3x and x = 4, what is y?",options:["7","12","34"],correct:1,explanation:"y = 3 x 4 = 12."}]},{id:"mfn-l2",title:"Reading a graph",icon:"graph",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A point on a graph is two numbers",content:'A graph shows pairs of numbers as points: how far across (x) and how far up (y). Saying "at x=2, y=6" means the point is 2 across and 6 up.'},{type:"multiple_choice",question:"On a graph, at x=2 the height is y=6. If x increases to 3 and the line rises by 2 more, what is y at x=3?",options:["7","8","6"],correct:1,explanation:"y was 6 at x=2; rising by 2 more gives y = 6 + 2 = 8 at x=3."},{type:"translate",question:"A graph shows that at x=4, y=10. What is y at x=4?",correct:"10",explanation:"The description states the value directly: y=10 when x=4."},{type:"multiple_choice",question:"A graph passes through the point where x=0 and y=5. What is this point usually called?",options:["the origin","the y-intercept","the slope"],correct:1,explanation:"The point where a graph crosses the y-axis (x=0) is called the y-intercept."},{type:"translate",question:"A graph shows y=9 when x=1, and y=12 when x=2. By how much did y increase?",correct:"3",explanation:"12 - 9 = 3."},{type:"multiple_choice",question:"The point where x=0 and y=0 is called",options:["the intercept","the origin","the slope"],correct:1,explanation:"The point (0, 0) is called the origin."},{type:"translate",question:"A graph shows y=6 at x=2, then y=6 again at x=5. Did y change between these points?",correct:"no",acceptable:["no it stayed the same","no, it did not change"],explanation:"y stayed 6 in both cases, so it did not change."}]},{id:"mfn-l3",title:"Slope and intercept",icon:"m",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"y = mx + b",content:"A straight line is written y = mx + b, where m is the slope (how steep the line is, per step across) and b is the y-intercept (the value of y when x = 0). Example: y = 2x + 3 with x = 5 -- y = 2(5) + 3 = 10 + 3 = 13."},{type:"translate",question:"y = 2x + 3. What is y when x = 5?",correct:"13",explanation:"y = 2(5) + 3 = 10 + 3 = 13."},{type:"multiple_choice",question:"y = 3x - 2. What is y when x = 4?",options:["9","10","14"],correct:1,explanation:"y = 3(4) - 2 = 12 - 2 = 10."},{type:"translate",question:"y = 4x + 1. What is y when x = 2?",correct:"9",explanation:"y = 4(2) + 1 = 8 + 1 = 9."},{type:"multiple_choice",question:"In y = 5x + 7, what is the y-intercept (value of y when x=0)?",options:["5","7","0"],correct:1,explanation:"When x = 0, y = 5(0) + 7 = 7, so the y-intercept is 7."},{type:"translate",question:"y = -1x + 4 (that is, y = 4 - x). What is y when x = 2?",correct:"2",explanation:"y = -1(2) + 4 = -2 + 4 = 2."},{type:"multiple_choice",question:"In y = 6x - 1, what is the slope m?",options:["6","-1","1"],correct:0,explanation:"The number multiplying x is the slope: m = 6."}]},{id:"mfn-l4",title:"Function or not: tables of values",icon:"table",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"One input cannot give two different outputs",content:"A table of input-output pairs represents a function only if no input repeats with a different output. If x=2 gives y=6 in one row and x=2 gives y=9 in another row, that is not a function, because the same input gave two different outputs."},{type:"multiple_choice",question:"A table has: x=1,y=2 and x=1,y=3. Is this a function?",options:["Yes","No","Cannot tell"],correct:1,explanation:"The same input (x=1) gives two different outputs (2 and 3), so this is not a function."},{type:"multiple_choice",question:"A table has: x=1,y=2 and x=2,y=2. Is this a function?",options:["Yes","No","Cannot tell"],correct:0,explanation:"Each input has exactly one output; different inputs are allowed to share the same output, so this is a function."},{type:"translate",question:"A table has x=3,y=5 and x=3,y=5 (the same pair repeated). Is this a function? (yes/no)",correct:"yes",explanation:"The input x=3 always gives the same output y=5, even repeated, so this is a function."},{type:"multiple_choice",question:"A table has: x=4,y=8; x=5,y=10; x=4,y=20. Is this a function?",options:["Yes","No","Cannot tell"],correct:1,explanation:"x=4 appears twice with different outputs (8 and 20), so this is not a function."},{type:"translate",question:"A table has x=0,y=1; x=1,y=1; x=2,y=1 (every input gives the same output). Is this a function? (yes/no)",correct:"yes",explanation:"Each input still gives exactly one output (always 1), so it is a function."},{type:"multiple_choice",question:"What makes a table of values NOT a function?",options:["Two different inputs giving the same output","One input appearing twice with two different outputs","The table having many rows"],correct:1,explanation:"A repeated input with two different outputs breaks the one-output-per-input rule that defines a function."}]},{id:"mfn-l5",title:"Course control: rules, graphs, and slope",icon:"🏆",xp:45,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Show what was learned",content:"This control test checks evaluating a function, reading a described graph, computing with slope and intercept, and telling a function from a non-function table."},{type:"translate",question:"y = 3x + 1. What is y when x = 4?",correct:"13",explanation:"y = 3(4) + 1 = 12 + 1 = 13."},{type:"multiple_choice",question:"A graph shows y=4 at x=1, and rises by 3 to reach x=2. What is y at x=2?",options:["7","5","12"],correct:0,explanation:"4 + 3 = 7."},{type:"translate",question:"y = 2x - 5. What is y when x = 6?",correct:"7",explanation:"y = 2(6) - 5 = 12 - 5 = 7."},{type:"multiple_choice",question:"A table has: x=2,y=4 and x=2,y=9. Is this a function?",options:["Yes","No"],correct:1,explanation:"The same input x=2 gives two different outputs, so it is not a function."},{type:"multiple_choice",question:"In y = 7x + 2, what is the y-intercept?",options:["7","2","9"],correct:1,explanation:"When x = 0, y = 7(0) + 2 = 2."}]}]}]},"math-trigonometry":{title:"Trigonometry",color:"#7c3aed",sections:[{id:"mtr-sec",title:"Right triangles and rotation",unlocked:!0,lessons:[{id:"mtr-l1",title:"The 3-4-5 triangle",icon:"△",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A right triangle with whole-number sides",content:"A right triangle with legs 3 and 4 and hypotenuse 5 is called a 3-4-5 triangle, and it is a genuine right triangle because 3 squared plus 4 squared equals 5 squared: 9 + 16 = 25, and 5 squared is also 25."},{type:"translate",question:"What is 3 squared plus 4 squared?",correct:"25",explanation:"3 squared is 9, 4 squared is 16, and 9 + 16 = 25."},{type:"multiple_choice",question:"What is 5 squared?",options:["10","25","15"],correct:1,explanation:"5 squared is 5 x 5 = 25."},{type:"translate",question:"In a 3-4-5 triangle, which side is the hypotenuse (the longest side, opposite the right angle)?",correct:"5",explanation:"The hypotenuse is the longest side: 5."},{type:"multiple_choice",question:"Why is a triangle with sides 3, 4, 5 a right triangle?",options:["Because 3 + 4 = 5 + 2","Because 3 squared + 4 squared = 5 squared","Because all sides are whole numbers"],correct:1,explanation:"A triangle is a right triangle exactly when the sum of the squares of the two shorter sides equals the square of the longest side: 9 + 16 = 25."},{type:"translate",question:"What are the two legs (the two shorter sides) of a 3-4-5 triangle?",correct:"3 and 4",acceptable:["3, 4","4 and 3","4, 3"],explanation:"The two legs are 3 and 4; the hypotenuse is 5."}]},{id:"mtr-l2",title:"Sine, cosine, and tangent",icon:"sin",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Three ratios from a right triangle",content:"For an angle in a right triangle: sine = opposite / hypotenuse, cosine = adjacent / hypotenuse, tangent = opposite / adjacent. Using a 3-4-5 triangle where the opposite side is 3, the adjacent side is 4, and the hypotenuse is 5: sine = 3/5 = 0.6, cosine = 4/5 = 0.8, tangent = 3/4 = 0.75."},{type:"translate",question:"Opposite = 3, hypotenuse = 5. What is sine, as a decimal?",correct:"0.6",acceptable:["3/5",".6"],explanation:"sine = opposite / hypotenuse = 3/5 = 0.6."},{type:"multiple_choice",question:"Adjacent = 4, hypotenuse = 5. What is cosine, as a decimal?",options:["0.6","0.8","0.75"],correct:1,explanation:"cosine = adjacent / hypotenuse = 4/5 = 0.8."},{type:"translate",question:"Opposite = 3, adjacent = 4. What is tangent, as a decimal?",correct:"0.75",acceptable:["3/4"],explanation:"tangent = opposite / adjacent = 3/4 = 0.75."},{type:"multiple_choice",question:"Which ratio is opposite divided by hypotenuse?",options:["sine","cosine","tangent"],correct:0,explanation:"sine = opposite / hypotenuse, by definition."},{type:"translate",question:"In a 3-4-5 triangle, opposite=3, hypotenuse=5, adjacent=4. What is sine plus cosine, as a decimal? (0.6 + 0.8)",correct:"1.4",explanation:"sine = 0.6, cosine = 0.8, and 0.6 + 0.8 = 1.4."},{type:"multiple_choice",question:"Which ratio is adjacent divided by hypotenuse?",options:["sine","cosine","tangent"],correct:1,explanation:"cosine = adjacent / hypotenuse, by definition."}]},{id:"mtr-l3",title:"Degrees around a circle",icon:"°",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"A full turn is 360 degrees",content:"A full circle is 360 degrees. A quarter turn is 90 degrees (360 / 4 = 90), a half turn is 180 degrees (360 / 2 = 180), and a three-quarter turn is 270 degrees (360 - 90 = 270, or 3 x 90 = 270)."},{type:"translate",question:"How many degrees are in a full turn?",correct:"360",explanation:"A full circle is 360 degrees."},{type:"multiple_choice",question:"How many degrees are in a quarter turn?",options:["90","180","45"],correct:0,explanation:"360 / 4 = 90."},{type:"translate",question:"How many degrees are in a half turn?",correct:"180",explanation:"360 / 2 = 180."},{type:"multiple_choice",question:"How many degrees are in a three-quarter turn?",options:["180","270","360"],correct:1,explanation:"3 x 90 = 270, or 360 - 90 = 270."},{type:"translate",question:"A shape turns 180 degrees, then turns another 90 degrees. How many degrees has it turned in total?",correct:"270",explanation:"180 + 90 = 270."}]},{id:"mtr-l4",title:"Describing a rotation",icon:"↻",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Angle and plain words for the same turn",content:"An angle of rotation can be described in plain words: 90 degrees is a quarter turn, 180 degrees is a half turn, 270 degrees is a three-quarter turn, and 360 degrees is a full turn (back to the start)."},{type:"multiple_choice",question:"90 degrees is described as",options:["a quarter turn","a half turn","a full turn"],correct:0,explanation:"90 degrees is one quarter of 360, a quarter turn."},{type:"translate",question:"What angle, in degrees, is a half turn?",correct:"180",explanation:"A half turn is half of 360, which is 180."},{type:"multiple_choice",question:"A full turn (360 degrees) brings a shape back to",options:["a completely new position","its starting position","a quarter turn from start"],correct:1,explanation:"360 degrees is the whole circle, so it returns to where it started."},{type:"translate",question:"A wheel turns three-quarters of a full circle. How many degrees is that?",correct:"270",explanation:"Three-quarters of 360 is 270 (360 x 3/4 = 270)."},{type:"multiple_choice",question:"A shape rotates 90 degrees, then another 90 degrees. What single turn is this equal to?",options:["a quarter turn","a half turn","a three-quarter turn"],correct:1,explanation:"90 + 90 = 180 degrees, which is a half turn."}]},{id:"mtr-l5",title:"Course control: triangles and turns",icon:"🏆",xp:45,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Show what was learned",content:"This control test checks the 3-4-5 triangle, the sine/cosine/tangent ratios, and degrees of rotation, the way this course covered them."},{type:"translate",question:"What is 3 squared plus 4 squared?",correct:"25",explanation:"9 + 16 = 25."},{type:"multiple_choice",question:"Opposite = 3, hypotenuse = 5. What is sine?",options:["0.6","0.8","0.75"],correct:0,explanation:"sine = 3/5 = 0.6."},{type:"translate",question:"How many degrees are in a quarter turn?",correct:"90",explanation:"360 / 4 = 90."},{type:"multiple_choice",question:"Adjacent = 4, hypotenuse = 5. What is cosine?",options:["0.6","0.8","0.75"],correct:1,explanation:"cosine = 4/5 = 0.8."},{type:"translate",question:"A shape rotates 270 degrees. In plain words, what turn is this?",correct:"three-quarter turn",acceptable:["a three-quarter turn","three quarter turn"],explanation:"270 degrees is three-quarters of 360, a three-quarter turn."}]}]}]},"math-calculus":{title:"Rates of change",color:"#be123c",sections:[{id:"mcl-sec",title:"Derivative and integral, conceptually",unlocked:!0,lessons:[{id:"mcl-l1",title:"A derivative is a speed",icon:"d/dx",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"How fast is it changing right now",content:"A derivative describes how fast a quantity is changing at a single instant -- the same idea as a speedometer showing speed at this moment, not the average over a whole trip. If a car has driven further in the last minute than the minute before, its speed (its rate of change of distance) is increasing."},{type:"multiple_choice",question:"A derivative describes",options:["the total amount so far","how fast something is changing right now","the starting value only"],correct:1,explanation:"A derivative is the instantaneous rate of change -- how fast something is changing at this moment."},{type:"multiple_choice",question:"A car’s speedometer shows 60 km/h. This is closest to",options:["a derivative of position","an integral of position","a constant with no meaning"],correct:0,explanation:"Speed is the rate of change of position -- exactly what a derivative measures."},{type:"translate",question:"If a plant grows faster in week 2 than in week 1, has its rate of change (derivative of height) increased or decreased? (increased/decreased)",correct:"increased",explanation:"Growing faster means the rate of change is larger, so it increased."},{type:"multiple_choice",question:"Which of these is asking about a derivative?",options:["How much total rain fell this month?","How fast is the rain falling right now?","What is the total distance of the trip?"],correct:1,explanation:'A rate right now ("how fast... right now") is what a derivative captures.'},{type:"translate",question:"A car’s speed drops from 80 km/h to 50 km/h. Did its rate of change of position increase or decrease? (increase/decrease)",correct:"decrease",explanation:"A lower speed means a smaller rate of change of position, so it decreased."}]},{id:"mcl-l2",title:"Derivative of x squared",icon:"x²",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"The power rule: bring the power down and subtract one",content:"For x to a power n, the derivative is n times x to the power (n-1) -- the power rule. For x squared (n=2): the derivative is 2 times x to the power 1, which is 2x. So d/dx(x^2) = 2x. A concrete check: near x=2, x squared is climbing at a rate close to 2x = 2(2) = 4 -- squares just past 2 (like 2.01 squared = 4.0401) confirm the height rises about 4 times as fast as x moves."},{type:"translate",question:"Using the power rule (n times x to the n-1), what is the derivative of x squared?",correct:"2x",explanation:"n=2, so the derivative is 2 times x to the power (2-1)=1, giving 2x."},{type:"multiple_choice",question:"The power rule says the derivative of x^n is",options:["n times x^(n-1)","x^(n+1) divided by (n+1)","n times x^n"],correct:0,explanation:"The power rule: bring the exponent down as a multiplier, then subtract 1 from the exponent."},{type:"translate",question:"At x=2, the derivative of x squared (which is 2x) equals what number?",correct:"4",explanation:"2x at x=2 is 2(2) = 4 -- matching how fast x squared is climbing there."},{type:"multiple_choice",question:"What is the derivative of x squared, at x=5?",options:["10","25","5"],correct:0,explanation:"The derivative is 2x; at x=5, 2(5) = 10."},{type:"translate",question:"The derivative of x squared is 2x. What is the derivative at x=0?",correct:"0",explanation:"2(0) = 0."}]},{id:"mcl-l3",title:"Derivative of x cubed",icon:"x³",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"The same rule, one power higher",content:"For x cubed (n=3), the power rule gives: derivative = 3 times x to the power (3-1) = 3 times x squared, so d/dx(x^3) = 3x^2. Example: at x=2, the derivative is 3(2 squared) = 3(4) = 12."},{type:"translate",question:"Using the power rule, what is the derivative of x cubed?",correct:"3x^2",acceptable:["3x²","3x2"],explanation:"n=3, so the derivative is 3 times x to the power (3-1)=2, giving 3x^2."},{type:"multiple_choice",question:"At x=2, the derivative of x cubed (3x^2) equals",options:["6","8","12"],correct:2,explanation:"3x^2 at x=2 is 3(2^2) = 3(4) = 12."},{type:"translate",question:"What is the derivative of x cubed, at x=1? (3 times 1 squared)",correct:"3",explanation:"3(1^2) = 3(1) = 3."},{type:"multiple_choice",question:"Which matches the power rule pattern for x cubed?",options:["exponent 3 comes down as a multiplier, new exponent is 2","exponent 3 stays the same","exponent becomes 4"],correct:0,explanation:"The power rule brings the exponent (3) down as a multiplier and subtracts 1 from it, giving exponent 2."}]},{id:"mcl-l4",title:"An integral is an amount built up",icon:"∫",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"How much has accumulated",content:"An integral describes the total amount that has built up, undoing what a derivative does. If speed tells how fast distance is changing, then the integral of speed over time gives the total distance travelled -- the accumulated amount. Since the derivative of x squared is 2x, the integral (antiderivative) of 2x is x squared (plus a constant, since a flat starting amount does not change the rate). Checking backwards: differentiating x squared gives 2x again, confirming the integral was found correctly."},{type:"multiple_choice",question:"An integral describes",options:["how fast something changes right now","how much has built up in total","a single instant only"],correct:1,explanation:"An integral is the accumulated amount -- the running total, not the instantaneous rate."},{type:"translate",question:"The derivative of x squared is 2x. What is the antiderivative (integral) of 2x?",correct:"x^2",acceptable:["x²","x2"],explanation:"Since differentiating x squared gives 2x, the integral of 2x is x squared (working backwards)."},{type:"multiple_choice",question:"To check that the integral of 2x is x squared, what should be done?",options:["Multiply x squared by 2","Differentiate x squared and confirm it gives 2x back","Add 2 to x squared"],correct:1,explanation:"Differentiating the proposed integral should return the original expression: d/dx(x^2) = 2x, confirming it."},{type:"translate",question:"If speed is the derivative of distance, what does the integral of speed over time give?",correct:"distance",acceptable:["the total distance","total distance travelled"],explanation:"Integrating speed accumulates it back into the total distance travelled."},{type:"multiple_choice",question:"A tank fills at a steady rate. The integral of the fill rate over time gives",options:["the fill rate itself","the total amount of water in the tank","the size of the tank"],correct:1,explanation:"Integrating a rate over time gives the accumulated amount -- here, the total water that has built up."}]},{id:"mcl-l5",title:"Course control: derivative and integral",icon:"🏆",xp:45,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Show what was learned",content:"This control test checks the derivative as an instantaneous rate, the power rule for x squared and x cubed, and the integral as an accumulated amount."},{type:"multiple_choice",question:"A derivative measures",options:["a total so far","an instantaneous rate of change","a fixed starting value"],correct:1,explanation:"A derivative is the rate of change at an instant."},{type:"translate",question:"What is the derivative of x squared?",correct:"2x",explanation:"Power rule with n=2: 2x^1 = 2x."},{type:"translate",question:"What is the derivative of x cubed?",correct:"3x^2",acceptable:["3x²","3x2"],explanation:"Power rule with n=3: 3x^2."},{type:"multiple_choice",question:"An integral measures",options:["an instantaneous rate","an accumulated amount","a single point only"],correct:1,explanation:"An integral is the total amount built up."},{type:"translate",question:"What is the integral (antiderivative) of 2x?",correct:"x^2",acceptable:["x²","x2"],explanation:"Since d/dx(x^2) = 2x, the integral of 2x is x^2."}]}]}]},"logic-proof":{title:"Logic and proof",color:"#1e293b",sections:[{id:"lp-sec",title:"Valid reasoning, and proof versus persuasion",unlocked:!0,lessons:[{id:"lp-l1",title:"Modus ponens: a valid form",icon:"→",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"If P then Q; P; therefore Q",content:"Modus ponens is a valid argument form: if P then Q; P is true; therefore Q is true. Example: if it rains, the ground gets wet (if P then Q); it is raining (P); therefore the ground gets wet (Q). This form is always valid -- when the premises are true, the conclusion must be true."},{type:"multiple_choice",question:'"If it rains, the ground gets wet. It is raining. Therefore, the ground gets wet." What form of reasoning is this?',options:["modus ponens (valid)","affirming the consequent (a fallacy)","no valid form"],correct:0,explanation:"This matches if P then Q; P; therefore Q -- modus ponens, a valid form."},{type:"multiple_choice",question:"Is modus ponens (if P then Q; P; therefore Q) valid or invalid?",options:["valid","invalid","sometimes valid"],correct:0,explanation:"Modus ponens is a standard valid form in classical logic: true premises guarantee a true conclusion."},{type:"translate",question:'Fill the missing step: "If a shape is a square, it has four equal sides. This shape is a square. Therefore, ___."',correct:"it has four equal sides",acceptable:["this shape has four equal sides","the shape has four equal sides"],explanation:"By modus ponens, since the shape is a square (P), the consequence Q (four equal sides) follows."},{type:"multiple_choice",question:'"If n is even, n squared is even. n is even. Therefore n squared is even." This argument is',options:["valid, by modus ponens","invalid","neither valid nor invalid"],correct:0,explanation:"This is exactly the shape if P then Q; P; therefore Q -- valid by modus ponens."}]},{id:"lp-l2",title:"Affirming the consequent: a fallacy",icon:"✗",xp:30,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"If P then Q; Q; therefore P -- invalid",content:"Affirming the consequent is a well-known formal fallacy: if P then Q; Q is true; therefore P is true. This does NOT follow, because Q could be true for some other reason. Example: if it rains, the ground gets wet (if P then Q); the ground is wet (Q); therefore it rained (P) -- invalid, because the ground could be wet from a sprinkler instead."},{type:"multiple_choice",question:'"If it rains, the ground gets wet. The ground is wet. Therefore, it rained." Is this valid?',options:["Yes, valid","No, this is affirming the consequent, a fallacy","Yes, because wet ground always means rain"],correct:1,explanation:"The ground could be wet for another reason (e.g. a sprinkler), so Q being true does not guarantee P -- this is the fallacy of affirming the consequent."},{type:"multiple_choice",question:"Affirming the consequent has the form:",options:["if P then Q; P; therefore Q","if P then Q; Q; therefore P","if P then Q; not P; therefore not Q"],correct:1,explanation:"Affirming the consequent takes if P then Q and the truth of Q, and wrongly concludes P."},{type:"translate",question:'"If a number is a multiple of 4, it is even. The number 6 is even. Therefore, 6 is a multiple of 4." Is this argument valid? (yes/no)',correct:"no",explanation:"This affirms the consequent (evenness) and wrongly concludes the antecedent (multiple of 4); 6 is even but not a multiple of 4, showing the form can produce a false conclusion from a true premise."},{type:"multiple_choice",question:"Why is affirming the consequent unreliable?",options:["Because Q could be true for a reason other than P","Because P is always false","Because Q is always false"],correct:0,explanation:"Q being true does not rule out other causes of Q, so P cannot be safely concluded."}]},{id:"lp-l3",title:"Proof versus persuasion",icon:"⚖",xp:25,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Necessary steps versus appeals",content:'A proof is a chain of steps that must follow necessarily from premises or definitions -- if the steps are valid and the premises true, the conclusion cannot be false. A persuasion instead appeals to authority, emotion, or popularity ("everyone agrees", "a famous person said so"), and can sound compelling while still being false, because none of those appeals force the conclusion to be true.'},{type:"multiple_choice",question:"Which of these is closest to a proof rather than a persuasion?",options:['"A famous scientist believes it, so it must be true."','"Given the definition of an even number, this conclusion follows by necessary steps."','"Everyone I know agrees with this."'],correct:1,explanation:"A proof rests on definitions and necessary steps, not on who believes it or how many people agree."},{type:"multiple_choice",question:'"This must be true because a popular expert said so." This is an appeal to',options:["authority","a valid proof","a definition"],correct:0,explanation:"Relying on who said it, rather than on necessary steps from premises, is an appeal to authority -- a persuasion, not a proof."},{type:"translate",question:"Can a persuasion (appeal to authority, emotion, or popularity) still turn out to be false even if it sounds compelling? (yes/no)",correct:"yes",explanation:"A persuasion does not force the conclusion to be true, so it can be false despite sounding compelling."},{type:"multiple_choice",question:"What makes a proof different from a persuasion?",options:["A proof is always longer","A proof follows necessarily from premises or definitions; a persuasion relies on appeals that do not guarantee truth","A proof uses more difficult words"],correct:1,explanation:"The defining difference is necessity: a valid proof cannot have true premises and a false conclusion, while a persuasion can."}]},{id:"lp-l4",title:"A direct proof: n even implies n squared even",icon:"∴",xp:35,unlocked:!0,type:"lesson",work:"classwork",exercises:[{type:"lecture",question:"Walking the proof step by step",content:'Claim: if a number is even, its square is even. Proof: let n be even. By the definition of even, n = 2k for some integer k. Then n squared = (2k) squared = 4k squared = 2(2k squared). Since 2k squared is an integer, n squared is 2 times an integer, so n squared is even. Each step follows necessarily from the one before, using only the definition of "even" (a multiple of 2) -- this is a proof, not a persuasion.'},{type:"multiple_choice",question:"The definition of an even number n used in this proof is",options:["n = 2k for some integer k","n is a positive number","n squared is even"],correct:0,explanation:"The proof starts from the definition: an even number can be written as 2 times some integer k."},{type:"translate",question:"If n = 2k, what does n squared equal, written out? ((2k) squared = ?)",correct:"4k^2",acceptable:["4k squared","4k²","4 k^2"],explanation:"(2k)^2 = 2^2 times k^2 = 4k^2."},{type:"multiple_choice",question:"Why does 4k squared show that n squared is even?",options:["Because 4k squared can be written as 2 times (2k squared), and 2k squared is an integer","Because 4 is an even number by itself","Because k is always even"],correct:0,explanation:"4k^2 = 2(2k^2); since 2k^2 is an integer, n^2 is 2 times an integer, which is exactly the definition of even."},{type:"translate",question:'Fill the missing step: "n^2 = 4k^2 = 2(2k^2). Since 2k^2 is an integer, n^2 is 2 times an integer, hence ___."',correct:"n^2 is even",acceptable:["n squared is even","even"],explanation:'Being 2 times an integer is exactly what "even" means, so the conclusion is that n squared is even.'},{type:"multiple_choice",question:"This proof is a direct proof because",options:["it assumes the opposite and finds a contradiction","it proceeds straight from the definition through necessary algebraic steps to the conclusion","it relies on many examples"],correct:1,explanation:"A direct proof starts from the premises/definitions and reasons forward step by step to the conclusion, which is exactly what happens here."}]},{id:"lp-l5",title:"Course control: valid reasoning and proof",icon:"🏆",xp:45,unlocked:!0,type:"test",work:"control",exercises:[{type:"lecture",question:"Show what was learned",content:"This control test checks telling modus ponens from affirming the consequent, telling a proof from a persuasion, and following the direct proof that an even number squared is even."},{type:"multiple_choice",question:'"If x is a multiple of 6, x is even. x is a multiple of 6. Therefore x is even." What form is this?',options:["modus ponens (valid)","affirming the consequent (a fallacy)"],correct:0,explanation:"This is if P then Q; P; therefore Q -- modus ponens, valid."},{type:"multiple_choice",question:'"If x is a multiple of 6, x is even. x is even. Therefore x is a multiple of 6." What form is this?',options:["modus ponens (valid)","affirming the consequent (a fallacy)"],correct:1,explanation:"This is if P then Q; Q; therefore P -- affirming the consequent; 8 is even but not a multiple of 6, showing it can fail."},{type:"translate",question:"If n = 2k, what does n squared equal in expanded form? (2k)^2 = ?",correct:"4k^2",acceptable:["4k squared","4k²"],explanation:"(2k)^2 = 4k^2."},{type:"multiple_choice",question:'A conclusion reached only because "most people believe it" rests on',options:["a necessary proof step","an appeal to popularity, a persuasion","the definition of even"],correct:1,explanation:"Popularity does not force truth, so this is a persuasion, not a proof."},{type:"translate",question:"n^2 = 4k^2 = 2(2k^2), and 2k^2 is an integer. What property of n^2 does this prove? (one word)",correct:"even",explanation:"n^2 being 2 times an integer is exactly what makes it even."}]}]}]}};e.s(["COURSES",0,o],69251)}]);